-- VT-L2 Module 2 — Advanced Optical Aids (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip remote visual testing (RVT) & pemilihan instrumen', '{"slides":[{"heading":"Kapan VT langsung tidak cukup","body":"Direct VT mensyaratkan mata berada dalam jarak <=600 mm (24 in) dari permukaan dengan sudut pandang minimal >=30 derajat dan iluminasi minimum 1000 lux (100 fc) pada area of interest. Bila akses fisik tidak memungkinkan — internal pipa, bore turbin, casting passage, tube boiler, blade engine — Level II beralih ke Remote Visual Testing (RVT) memakai optical aids. RVT diakui ASME V Article 9 dan ISO 17637 selama resolusi dan iluminasi terbukti setara direct VT melalui demonstrasi pada artifact referensi."},{"heading":"Tiga keluarga alat optik","body":"1) Rigid borescope: tabung kaku berisi rangkaian lensa relay (rod-lens/Hopkins), kualitas gambar TERBAIK dan resolusi tertinggi, hanya untuk jalur akses lurus. 2) Flexible fiberscope: berkas serat optik koheren (coherent fiber bundle) yang dapat diartikulasikan, untuk jalur berliku. 3) Video borescope (videoscope): sensor CCD/CMOS di ujung probe, citra ditampilkan di monitor dan mendukung pengukuran. Level II wajib memilih alat sesuai geometri akses dan tujuan inspeksi, bukan sekadar yang tersedia."},{"heading":"Lima parameter pemilihan teknis","body":"Pilih berdasarkan: (a) Diameter probe — harus muat di akses port (umum 4-8 mm; mikro 1.0-2.4 mm). (b) Working length — panjang jangkauan (0.3 m s/d >30 m pada videoscope). (c) Field of View (FOV) — sudut pandang umumnya 40-120 derajat. (d) Depth of Field (DOF) — rentang jarak yang tetap fokus. (e) Direction of View (DOV) — arah pandang 0 derajat (forward), 90 derajat (side), atau retro/oblique. Diameter besar = serat/optik lebih banyak = resolusi lebih tinggi tetapi akses lebih terbatas."},{"heading":"Demonstrasi kesetaraan (resolution test)","body":"Sebelum RVT menggantikan direct VT untuk keputusan keberterimaan, prosedur harus membuktikan sistem mampu menampilkan artifact buatan terkecil yang relevan. Praktik umum: tempatkan karakter (mis. huruf kecil) atau garis/celah berukuran kalibrasi di jarak kerja maksimum; jika terbaca jelas di monitor, resolusi dianggap memadai. Catat jenis alat, tip, jarak kerja, iluminasi, dan hasil demonstrasi dalam laporan — ini adalah audit trail keberterimaan RVT yang dipertanggungjawabkan Level II."}]}', 470, NULL),
  (2, 'reading', 'Rigid borescope & flexible fiberscope — anatomi dan keterbatasan', '{"slides":[{"heading":"Rigid borescope: relay-lens optics","body":"Citra dibawa oleh rangkaian lensa relay (rod-lens/Hopkins design) di dalam tabung baja kaku. Karena tidak ada serat optik penghantar citra, tidak ada efek honeycomb dan resolusinya paling tinggi di antara ketiga keluarga. Cahaya disuplai serat optik di sekeliling lensa dari light source eksternal. Diameter umum 4-10 mm, panjang sampai sekitar 1 m. Trade-off: hanya jalur lurus; tabung tidak boleh menanggung beban lateral karena lensa relay sensitif terhadap defleksi."},{"heading":"Flexible fiberscope: coherent fiber bundle","body":"Memakai dua berkas serat: incoherent bundle untuk menghantar cahaya, dan coherent (image) bundle di mana setiap serat menempati posisi relatif sama di kedua ujung sehingga citra utuh dihantar. Ujung distal dapat diartikulasikan (articulation) hingga sekitar 180 derajat melalui kontrol di handle, memungkinkan navigasi tikungan. Diameter kecil tersedia (mis. 2.4-6 mm), tetapi makin kecil diameter makin sedikit serat sehingga resolusi turun."},{"heading":"Keterbatasan fiberscope","body":"Resolusi dibatasi jumlah serat dalam image bundle — makin sedikit serat, makin kasar gambar (pixelation honeycomb/chicken-wire). Serat patah muncul sebagai titik hitam permanen pada citra dan bertambah seiring usia atau penekukan berlebih; alat dengan terlalu banyak titik mati harus dipensiunkan. Fiberscope juga cenderung kehilangan kontras dibanding rigid borescope dan warna dapat bergeser. Karena interpretasi bersifat subjektif, dokumentasi foto sulit setara videoscope."},{"heading":"Iluminasi & light source","body":"Semua optical aids butuh sumber cahaya kuat (halogen, metal-halide, atau LED) karena cahaya melemah sepanjang fiber dan dipantulkan dari permukaan internal. Iluminasi pada area of interest tetap harus memadai (prinsip >=1000 lux / 100 fc untuk general VT tetap menjadi acuan ketajaman). Hindari hot-spot/glare pada permukaan mengkilap dengan mengatur intensitas dan sudut; permukaan korosi gelap butuh cahaya lebih tinggi dan kadang oblique lighting untuk menonjolkan topografi indikasi."}]}', 490, NULL),
  (3, 'reading', 'Video borescope (videoscope) & pengukuran indikasi', '{"slides":[{"heading":"Sensor di ujung (chip-on-tip)","body":"Videoscope menempatkan sensor CCD atau CMOS langsung di tip probe, sehingga citra tidak melewati fiber dan kualitas jauh melebihi fiberscope (tidak ada honeycomb, resolusi mengikuti piksel sensor). Citra tampil di monitor LCD dan mudah direkam sebagai foto/video resolusi tinggi untuk audit trail. Artikulasi tip umumnya 4-arah (up/down/left/right); banyak unit mendukung steering presisi dan tip adaptor (forward/side view) yang dapat diganti."},{"heading":"Pengukuran: stereo, comparison & phase","body":"Videoscope memungkinkan ukur indikasi tanpa kontak. (1) Comparison (shadow/scale) measurement: butuh objek referensi berukuran diketahui pada bidang yang sama; akurasi terbatas oleh perspektif. (2) Stereo measurement: tip optik khusus menghasilkan dua sudut pandang sehingga sistem menghitung koordinat 3D via parallax — paling akurat untuk panjang, kedalaman, dan luas indikasi. (3) Phase/3D-phase measurement: proyeksi pola terstruktur untuk peta kedalaman penuh permukaan. Selalu kalibrasi dan catat metode serta tip yang dipakai."},{"heading":"Faktor akurasi & rujukan ke code","body":"Akurasi turun bila: indikasi jauh dari tip (di luar DOF), sudut pandang miring, permukaan reflektif menghasilkan silau, atau kalibrasi tip salah. Praktik baik: dekatkan tip hingga indikasi tajam dan mengisi frame, jaga sudut mendekati tegak lurus, ulangi pengukuran 2-3 kali dan ambil rata-rata, dokumentasikan serial tip + tanggal kalibrasi. Nilai dari borescope adalah ESTIMASI — keputusan tolak/terima tetap mengacu kriteria code (mis. AWS D1.1: undercut <=1 mm/1/32 in untuk sambungan statis umum, <=0.25 mm untuk komponen cyclically loaded/thin; crack & lack of fusion SELALU ditolak), dan bila kritis diverifikasi metode lain seperti UT untuk kedalaman."},{"heading":"Aplikasi tipikal & pemilihan DOV","body":"Forward view (0 derajat) untuk inspeksi ujung lubang/bore dan navigasi maju. Side view (90 derajat) untuk dinding ID pipa, bore silinder, dan akar las internal. Penerapan: tube boiler/heat exchanger (pitting, scaling), bilah turbin gas (FOD, crack, coating loss), casting passage (porosity, inclusion), las internal pipa proses (root concavity, burn-through, suckback), dan ruang sempit pesawat. Catat lokasi indikasi dengan referensi datum (jarak masuk, posisi arah jam) agar dapat ditelusuri ulang untuk repair verification."}]}', 510, NULL),
  (4, 'reading', 'Prosedur RVT, perawatan alat & batasan interpretasi', '{"slides":[{"heading":"Elemen prosedur RVT (Level II menulis)","body":"Prosedur tertulis (mengikuti ASME V Article 9 / ISO 17637) memuat: jenis & model alat, tip/DOV/FOV, working length, sumber & tingkat cahaya, jarak kerja maksimum, metode demonstrasi resolusi, teknik pembersihan permukaan sebelum inspeksi, kriteria keberterimaan code yang berlaku, metode pengukuran indikasi, serta format perekaman citra & pelaporan. Level II bertanggung jawab menyusun, menyetujui, dan mendemonstrasikan teknik ini."},{"heading":"Persiapan permukaan & navigasi","body":"Bersihkan area dari kerak, minyak, dan residu agar indikasi tidak tertutup; flush dan keringkan internal bila perlu. Saat memasukkan probe, lindungi insertion tube dari tepi tajam dan jangan memaksa tekukan melebihi minimum bend radius alat. Gunakan guide tube pada tube panjang. Rekam datum awal (titik nol) sehingga setiap indikasi punya koordinat (kedalaman masuk + posisi arah jam) untuk pengulangan inspeksi dan repair verification."},{"heading":"Perawatan & inspeksi alat","body":"Sebelum & sesudah pakai: periksa lensa objektif/jendela tip dari goresan & kotoran, cek serat mati (titik hitam) pada fiberscope, uji artikulasi penuh, dan periksa insertion tube dari kink atau sobek (cairan kerja dapat masuk dan merusak optik). Simpan tergulung longgar pada radius besar, hindari panas dan zat kimia di luar rating alat. Alat yang citranya menurun di bawah ambang demonstrasi resolusi tidak boleh dipakai untuk keputusan keberterimaan."},{"heading":"Batasan & etika interpretasi","body":"Optical aids memperluas akses tetapi tetap surface method: hanya mendeteksi yang terlihat di permukaan internal, tidak mengukur defek subsurface. Distorsi perspektif, pergeseran warna fiber, dan silau bisa menyesatkan; jangan menafsirkan refleksi sebagai crack atau genangan air sebagai indikasi. Bila ragu, bersihkan ulang, ubah sudut/cahaya, atau verifikasi dengan metode lain. Semua keputusan terdokumentasi dengan citra pendukung — inilah dasar audit trail yang dipertanggungjawabkan Level II menjelang jalur CWI (AWS QC1)."}]}', 450, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Optical Aids', '{"description":"7 soal: pemilihan & prinsip rigid/fiber/video borescope, pengukuran indikasi, demonstrasi resolusi, rujukan ke kriteria code, dan batasan RVT.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 2 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Di antara ketiga keluarga optical aid, manakah yang memberikan kualitas gambar dan resolusi TERBAIK namun hanya dapat dipakai pada jalur akses lurus?',
   '["Flexible fiberscope dengan articulation 180 derajat","Video borescope dengan tip side-view","Rigid borescope (rod-lens/Hopkins)","Fiberscope mikro berdiameter 2.4 mm"]', 2,
   'Rigid borescope memakai rangkaian lensa relay (rod-lens/Hopkins) tanpa serat optik penghantar citra, sehingga tidak ada efek honeycomb dan resolusinya tertinggi. Konsekuensinya tabung kaku hanya bisa menjangkau jalur lurus.', 'Optical Aids', 'easy'),
  ('Pada flexible fiberscope, citra utuh dapat dihantar dari ujung distal ke mata pengamat karena adanya komponen apa?',
   '["Sensor CMOS yang dipasang di ujung tip","Coherent (image) fiber bundle yang posisi relatif tiap seratnya identik di kedua ujung","Rangkaian lensa relay rod-lens","Incoherent bundle yang khusus menghantar cahaya"]', 1,
   'Coherent/image bundle menjaga posisi relatif setiap serat identik di kedua ujung sehingga citra tersusun utuh. Incoherent bundle hanya menghantar cahaya, bukan citra; sensor CMOS dan rod-lens adalah ciri videoscope dan rigid borescope.', 'Optical Aids', 'medium'),
  ('Munculnya titik-titik hitam permanen pada gambar fiberscope yang jumlahnya bertambah seiring usia dan penekukan alat paling tepat dijelaskan oleh?',
   '["Serat optik dalam image bundle yang patah/mati","Iluminasi yang melebihi 1000 lux","Sensor CCD dengan piksel mati","Articulation yang dipakai melebihi 90 derajat"]', 0,
   'Setiap serat yang patah dalam coherent bundle menjadi titik hitam permanen pada citra dan jumlahnya bertambah karena penekukan/usia. Fiberscope dengan terlalu banyak serat mati harus dipensiunkan. Videoscope tidak memakai fiber untuk menghantar citra.', 'Equipment Maintenance', 'medium'),
  ('Metode pengukuran videoscope yang menggunakan dua sudut pandang dari tip optik khusus untuk menghitung dimensi 3D indikasi melalui parallax disebut?',
   '["Comparison (shadow) measurement","Direction-of-view calibration","Stereo measurement","Demonstrasi resolusi"]', 2,
   'Stereo measurement memakai tip optik yang menghasilkan dua perspektif sehingga sistem menghitung koordinat 3D lewat parallax — paling akurat untuk panjang/kedalaman/luas. Comparison measurement hanya membandingkan terhadap objek referensi pada bidang yang sama dan kurang akurat.', 'Measurement', 'medium'),
  ('Sebelum RVT (remote visual testing) boleh menggantikan direct VT untuk keputusan keberterimaan menurut ASME V Article 9 / ISO 17637, langkah verifikasi apa yang harus dilakukan dan dicatat?',
   '["Memastikan probe berdiameter di bawah 2.4 mm","Menyetel FOV ke 120 derajat","Mengganti light source ke halogen","Demonstrasi resolusi: artifact/karakter referensi terkecil harus terbaca jelas pada jarak kerja maksimum"]', 3,
   'Standar menuntut bukti kesetaraan: sistem harus mampu menampilkan artifact referensi terkecil yang relevan (mis. karakter/celah kalibrasi) di jarak kerja maksimum. Jenis alat, tip, jarak, iluminasi, dan hasil dicatat sebagai audit trail.', 'Procedure', 'hard'),
  ('Untuk menginspeksi dinding ID (internal diameter) sebuah pipa atau akar las internal di sepanjang sisi bore, direction of view (DOV) tip yang paling sesuai adalah?',
   '["Forward view 0 derajat","Side view 90 derajat","Open lens tanpa tip","Retro view ke arah operator"]', 1,
   'Side view 90 derajat mengarahkan pandangan tegak lurus ke dinding ID sehingga ideal untuk memeriksa permukaan samping bore dan akar las internal. Forward view 0 derajat cocok untuk navigasi maju dan inspeksi ujung lubang.', 'Optical Aids', 'medium'),
  ('Seorang inspektur Level II mengukur undercut pada akar las internal pipa baja struktural (sambungan statis) memakai videoscope dan memperoleh estimasi 0,8 mm. Bagaimana keputusan keberterimaan yang BENAR?',
   '["Tolak otomatis karena setiap undercut tidak boleh ada pada las apa pun","Terima tanpa rujukan code karena nilai videoscope bersifat absolut","Bandingkan terhadap kriteria code; pada AWS D1.1 sambungan statis undercut <=1 mm (1/32 in) umumnya diterima, jadi 0,8 mm dapat diterima dengan dokumentasi","Tolak karena optical aid tidak boleh dipakai untuk pengukuran apa pun"]', 2,
   'Nilai dari borescope adalah estimasi yang harus dirujuk ke kriteria code. AWS D1.1 mengizinkan undercut hingga 1 mm (1/32 in) untuk sambungan statis umum (batas lebih ketat 0,25 mm untuk komponen cyclically loaded/thin), sehingga 0,8 mm dapat diterima dengan dokumentasi citra. Crack dan lack of fusion selalu ditolak, tetapi tidak setiap undercut otomatis ditolak.', 'Code Interpretation', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 3 — Weld Profile Gauges (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Bridge Cam Gauge — penguasaan tingkat lanjut', '{"slides":[{"heading":"Anatomi & fungsi multi-parameter","body":"Bridge cam gauge (welding gauge) adalah alat tunggal yang mengukur beberapa parameter sambungan butt: tinggi reinforcement (cap height), kedalaman undercut, sudut preparasi bevel, dan misalignment/Hi-Lo. Komponen utama: badan jembatan (bridge) yang menumpu pada permukaan base metal di kedua sisi las, dan pointer berputar (rotating arm/cam) bertanda skala. Level II harus memilih parameter yang tepat dan mendokumentasikan tiap pembacaan secara terpisah dengan ID alat untuk audit trail."},{"heading":"Mengukur reinforcement & undercut","body":"Reinforcement: tumpukan kaki jembatan rata pada base metal, putar pointer turun hingga menyentuh puncak cap; baca tinggi (mm). Undercut: posisikan ujung pointer ke dalam alur undercut di toe las, baca kedalaman. Akurasi tipikal 0.1-0.5 mm tergantung model. Per AWS D1.1, undercut pada anggota statically loaded (thickness >25 mm) umumnya dibatasi <=1 mm (1/32 in); pada struktur cyclically loaded (fatigue) batas turun ke <=0.25 mm untuk arah transversal terhadap tegangan. Kesalahan umum: kaki jembatan tidak rata pada base metal sehingga pembacaan terlalu besar."},{"heading":"Sudut bevel & Hi-Lo","body":"Bridge cam dapat membaca sudut preparasi groove (umumnya 0-60 derajat) dengan menyelaraskan badan ke permukaan bevel — penting saat menilai fit-up sebelum las. Untuk misalignment (Hi-Lo) eksternal pada butt joint pipa/pelat, gunakan kaki sebagai datum pada satu sisi dan pointer turun ke permukaan sisi lain untuk membaca beda tinggi. Catatan: bridge cam mengukur Hi-Lo permukaan; untuk Hi-Lo internal akar pipa, alat Hi-Lo dedicated (welding alignment gauge) lebih akurat."},{"heading":"Kalibrasi, verifikasi & batas alat","body":"Bridge cam adalah alat mekanis tanpa kalibrasi formal, tetapi Level II wajib melakukan verifikasi periodik terhadap gauge block/feeler atau setting standard, mengecek keausan pointer dan ketegakan kaki, serta mencatat ID alat di laporan untuk audit trail. Resolusi terbatas (~0.5 mm pada model analog murah) — untuk toleransi ketat pakai versi dial/digital. Permukaan harus bersih dari spatter dan slag; sisa terak menaikkan pembacaan reinforcement secara palsu (overestimate)."}]}', 460, NULL),
  (2, 'reading', 'Fillet Weld Gauge — leg, throat & profil', '{"slides":[{"heading":"Konsep leg, throat & geometri fillet","body":"Pada fillet weld, leg size adalah panjang kaki di sepanjang masing-masing permukaan join; theoretical throat = 0.707 x leg (untuk fillet sama-kaki pada sambungan 90 derajat); actual throat diukur dari root ke face weld. Fillet weld gauge mengukur leg length langsung dan menilai apakah profil convex (cembung) atau concave (cekung). Spesifikasi drawing biasanya menyebut leg size (misal fillet 8 mm), jadi pembacaan leg adalah parameter penerimaan utama, sedangkan throat menentukan kapasitas menahan beban."},{"heading":"Dua tipe gauge & cara pakai","body":"Tipe 1 — Fillet weld gauge set (skala blade/wedge per ukuran, mis. 3, 5, 6, 8, 10, 12 mm): pilih blade yang pas, tempelkan dua sisi datum ke kedua kaki join; ujung blade menunjukkan apakah weld undersized, tepat, atau oversized untuk profil convex maupun concave. Setiap blade biasanya punya satu sisi convex dan satu sisi concave. Tipe 2 — Dial/adjustable fillet gauge: geser pointer sampai menyentuh face, baca leg/throat pada skala. Pilih tipe sesuai presisi yang dibutuhkan."},{"heading":"Convex vs concave & profil cacat","body":"Fillet convex menambah material tetapi convexity berlebih boros dan menjadi stress raiser pada transisi toe; concave dapat mengurangi throat efektif di bawah desain sehingga kapasitas beban turun. Gauge membantu deteksi insufficient throat, excessive convexity, dan unequal legs (kaki tidak sama panjang). Cacat profil terkait yang dinilai bersamaan: undercut pada toe dan overlap (cold lap) di toe — overlap selalu reject per AWS D1.1. Level II menilai kombinasi ukuran + profil, bukan hanya satu angka."},{"heading":"Penerimaan per kode & dokumentasi","body":"AWS D1.1 mengizinkan toleransi: leg/ukuran fillet boleh undersize terbatas asalkan kekurangan tidak melebihi nilai tertentu sepanjang panjang las yang dibatasi (lihat tabel acceptance edisi yang berlaku — Clause 8 pada edisi terkini, Section 6 pada edisi lama), sementara convexity maksimum dibatasi sebagai fungsi face width. Level II mendokumentasikan leg aktual tiap sisi, profil (convex/concave), dan setiap cacat toe. Catat unit secara konsisten (mm), ID gauge, dan posisi pengukuran agar dapat ditelusuri saat audit CWI/klien."}]}', 480, NULL),
  (3, 'reading', 'Taper Gauge & alat ukur celah lanjutan', '{"slides":[{"heading":"Taper gauge — prinsip baji","body":"Taper gauge (wedge/feeler taper) adalah baji bertingkat dengan skala linier yang dimasukkan ke dalam celah; kedalaman masuk menunjukkan lebar celah. Digunakan untuk mengukur root gap (fit-up sebelum las), lebar groove, dan dimensi celah/aperture yang tidak terjangkau caliper. Rentang tipikal 1-15 mm dengan resolusi ~0.5 mm (model batang) atau 0.1 mm (model dial). Pada VT Level II, taper gauge kunci untuk verifikasi fit-up — root gap yang salah adalah penyebab utama incomplete penetration."},{"heading":"Aplikasi fit-up & root opening","body":"Sebelum pengelasan, Level II memverifikasi root opening sesuai WPS (mis. 2-3 mm untuk banyak groove butt), land/root face, dan kesejajaran. Taper gauge dimasukkan ke root gap di beberapa titik sepanjang join untuk mendeteksi gap tidak seragam (tapered fit-up) yang menyebabkan burn-through di gap lebar atau lack of fusion / incomplete penetration di gap sempit. Dokumentasi pre-weld ini bagian dari hold point inspection dan audit trail."},{"heading":"Pit depth & alat profil terkait","body":"Untuk in-service inspection, pit depth gauge (dial/digital dengan jembatan datum) mengukur kedalaman korosi pitting dari permukaan referensi — penting untuk remaining wall thickness assessment. Hi-Lo gauge mengukur misalignment internal/eksternal pipa. Pit gauge dan taper gauge saling melengkapi: satu untuk kehilangan material (depth), satu untuk celah/lebar. Level II memilih kombinasi alat berdasarkan jenis cacat dan kode yang berlaku."},{"heading":"Sumber error & praktik terbaik","body":"Sumber error: pembengkokan baji pada celah sempit, paralaks pembacaan skala analog, permukaan kotor/terak, dan suhu (ekspansi termal pada celah panas). Praktik terbaik: bersihkan permukaan, ambil pembacaan ganda di beberapa titik dan laporkan nilai terburuk (worst case), verifikasi alat terhadap feeler/gauge block, dan catat ID alat. Untuk dokumentasi defensible (CWI/klien), sertakan foto skala terbaca berdampingan dengan defect — menghubungkan ke standar fotografi pada modul Documentation & Audit Trail."}]}', 440, NULL),
  (4, 'quiz', 'Mini-quiz — Weld Profile Gauges', '{"description":"8 soal penguasaan bridge cam, fillet gauge, dan taper gauge tingkat Level II.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 3 mini-quiz (8 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada bridge cam gauge, parameter manakah berikut ini yang TIDAK dapat diukur langsung oleh satu alat tersebut?',
   '["Tinggi reinforcement (cap height) pada butt weld","Kedalaman undercut pada toe las","Kandungan porositas internal di bawah permukaan","Sudut preparasi bevel groove"]', 2,
   'Bridge cam gauge adalah alat ukur dimensi permukaan: reinforcement, undercut, sudut bevel, dan misalignment. Porositas internal/subsurface tidak terukur secara visual/mekanis dan memerlukan metode volumetrik seperti RT atau UT.', 'Bridge Cam Gauge', 'easy'),
  ('Untuk struktur yang mengalami pembebanan siklik (cyclically/fatigue loaded), batas kedalaman undercut transversal menurut AWS D1.1 yang umum adalah:',
   '["Tidak ada batas selama tidak ada crack","<=3 mm (1/8 in)","<=1 mm (1/32 in)","<=0.25 mm"]', 3,
   'Pada anggota cyclically loaded, undercut transversal terhadap tegangan dibatasi lebih ketat (umumnya <=0.25 mm), sedangkan pada anggota statically loaded (thickness >25 mm) batasnya umumnya <=1 mm (1/32 in). Pengukuran kedalaman undercut inilah yang dilakukan dengan pointer bridge cam.', 'Code — AWS D1.1', 'medium'),
  ('Sisa terak (slag) yang tidak dibersihkan pada puncak cap saat mengukur reinforcement dengan bridge cam gauge akan menyebabkan:',
   '["Pembacaan reinforcement yang lebih tinggi secara palsu (overestimate)","Pembacaan reinforcement yang lebih rendah secara palsu","Tidak ada pengaruh karena pointer menembus terak","Hanya pengukuran sudut bevel yang menjadi tidak akurat"]', 0,
   'Terak menambah ketinggian palsu di puncak cap sehingga pointer berhenti lebih tinggi, menghasilkan reinforcement yang overestimate. Permukaan harus bersih dari spatter dan slag sebelum pengukuran dimensi apa pun.', 'Bridge Cam Gauge', 'medium'),
  ('Untuk fillet weld sama-kaki pada sambungan 90 derajat dengan leg 10 mm, theoretical throat-nya kira-kira:',
   '["5 mm","14.14 mm","7.07 mm","10 mm"]', 2,
   'Theoretical throat = 0.707 x leg. Untuk leg 10 mm: 0.707 x 10 = 7.07 mm. Hubungan ini penting karena throat menentukan kapasitas beban sambungan fillet, sedangkan gauge umumnya membaca leg.', 'Fillet Weld Gauge', 'medium'),
  ('Seorang inspektor menemukan fillet weld dengan profil sangat concave sehingga throat aktual lebih kecil dari desain. Konsekuensi utamanya adalah:',
   '["Reinforcement berlebih yang boros material","Throat efektif berkurang sehingga kapasitas menahan beban turun di bawah desain","Selalu menyebabkan overlap di toe las","Tidak masalah karena concave selalu lebih kuat dari convex"]', 1,
   'Profil concave dapat menurunkan throat efektif di bawah nilai desain sehingga kapasitas beban berkurang. Convex justru menambah material (boros) tetapi tidak mengurangi throat; overlap adalah cacat toe terpisah.', 'Fillet Weld Gauge', 'medium'),
  ('Pada fillet weld set gauge tipe blade/wedge bertanda ukuran (3, 5, 6, 8, 10, 12 mm), tiap blade umumnya memiliki dua sisi yang berbeda fungsi, yaitu:',
   '["Sisi metric dan sisi imperial pada parameter yang sama","Sisi untuk profil convex dan sisi untuk profil concave","Sisi untuk undercut dan sisi untuk porositas","Sisi untuk root gap dan sisi untuk reinforcement"]', 1,
   'Setiap blade fillet gauge biasanya memiliki satu sisi untuk menilai fillet convex dan sisi lain untuk fillet concave pada ukuran nominal yang sama, sehingga inspektor dapat menentukan undersize/oversize untuk kedua profil.', 'Fillet Weld Gauge', 'hard'),
  ('Sebelum pengelasan, taper gauge digunakan untuk memverifikasi root opening sesuai WPS. Jika root gap terlalu sempit dibanding spesifikasi, risiko cacat las yang paling mungkin adalah:',
   '["Burn-through karena terlalu banyak panas lolos","Excessive reinforcement pada cap","Undercut transversal pada toe","Lack of fusion / incomplete penetration pada akar"]', 3,
   'Root gap yang terlalu sempit menyulitkan penetrasi penuh ke akar sehingga berisiko lack of fusion / incomplete penetration. Sebaliknya, gap terlalu lebar berisiko burn-through. Karena itu taper gauge dipakai pada hold point fit-up.', 'Taper Gauge', 'medium'),
  ('Saat mengukur celah panas (hot joint) dengan taper gauge dan mengambil beberapa pembacaan di sepanjang root, praktik dokumentasi Level II yang paling defensible adalah:',
   '["Laporkan nilai worst case beserta ID alat dan beberapa titik pengukuran","Laporkan hanya nilai rata-rata tanpa mencatat ID alat","Ambil satu pembacaan di tengah join saja agar cepat","Tunda semua pengukuran sampai sambungan dingin total"]', 0,
   'Dokumentasi defensible (untuk audit CWI/klien) memerlukan pelaporan nilai terburuk dari beberapa titik, mencantumkan ID alat untuk traceability, dan menyadari pengaruh ekspansi termal. Rata-rata tunggal atau satu titik menyembunyikan variasi gap yang kritis.', 'Taper Gauge', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 4 — Documentation & Audit Trail (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Mengapa dokumentasi = bukti hukum', '{"slides":[{"heading":"Report adalah deliverable","body":"Di Level II, output VT bukan sekadar accept/reject di lapangan — output utama adalah dokumen inspeksi yang dapat ditelusuri (traceable) dan bertahan audit. Prinsip QA/QC: jika tidak terdokumentasi, dianggap tidak pernah dilakukan (''if it isn''t documented, it didn''t happen''). Report yang lemah dapat membatalkan inspeksi yang secara teknis sudah benar."},{"heading":"Konten minimum report VT","body":"Mengacu ASME Section V Article 9, AWS D1.1, dan praktik per AWS QC1: identifikasi komponen & weld ID, prosedur + nomor revisi yang dipakai, teknik (direct/remote, jenis optical aid), kondisi pencahayaan (minimum 1000 lux / 100 fc pada surface of interest), jarak & sudut pandang untuk direct VT (mata dalam ~600 mm / 24 in dari permukaan, sudut >=30 deg), acceptance standard (sebut edisi & clause), hasil per indikasi, nama & sertifikasi inspektur (level + tanggal kedaluwarsa), tanggal inspeksi, dan disposition accept/reject."},{"heading":"Acceptance standard harus disebut edisi","body":"Tidak cukup menulis ''AWS D1.1''. Sebut edisi tahun dan clause spesifik: batas undercut, kriteria profil, dan acceptance dapat berubah antar edisi. Edisi terkini menempatkan visual acceptance criteria di Clause 8, sedangkan edisi lama di Section 6. Menyebut clause/edisi yang salah dapat ditolak auditor dan menimbulkan tanggung jawab hukum bagi inspektur yang menandatangani."},{"heading":"Sign-off authority Level II","body":"Level II berwenang menandatangani final acceptance dan menyetujui (review/approve) report Level I. Tanda tangan inspektur mengikat secara kontraktual dan legal — di sinilah audit trail bermuara. Setiap koreksi pada report dilakukan dengan single-line strikethrough + paraf + tanggal; data lama harus tetap terbaca, tidak boleh dihapus/ditimpa (no obliteration)."}]}', 440, NULL),
  (2, 'reading', 'Standar fotografi inspeksi', '{"slides":[{"heading":"Foto = bukti, bukan dekorasi","body":"Foto harus reproducible dan menunjukkan kondisi sebenarnya. Wajib ada: scale reference (penggaris/coin kalibrasi atau gauge dalam frame), label identitas (weld ID + tanggal) yang terbaca, dan indikator orientasi. Foto tanpa skala tidak dapat dipakai untuk membuktikan dimensi indikasi (mis. panjang/kedalaman undercut)."},{"heading":"Pencahayaan & fokus untuk foto","body":"Gunakan pencahayaan yang konsisten dengan persyaratan VT (minimum 1000 lux pada area of interest). Hindari hotspot/refleksi spekular pada permukaan logam mengkilap — pakai cahaya menyudut (oblique/grazing light) untuk menonjolkan profil dan undercut. Pastikan depth of field cukup dan fokus tajam; tandai indikasi dengan marker yang tidak menutupi defect itu sendiri."},{"heading":"Foto dari optical aid","body":"Video borescope/videoscope menyimpan still & video beserta metadata (tanggal, kedalaman insertion, nomor frame). Untuk pengukuran via stereo/comparison measurement, simpan gambar mentah beserta nilai ukur dan probe/tip yang digunakan. Cantumkan magnifikasi & field of view agar pembaca tidak salah menafsirkan skala — magnifikasi tinggi tanpa skala dapat menipu persepsi ukuran."},{"heading":"Integritas file & no manipulation","body":"Audit melarang editing yang mengubah makna (cloning, contrast/curve ekstrem, crop yang menghilangkan konteks). Yang diperbolehkan: anotasi non-destruktif (panah, kotak, skala kalibrasi) pada salinan, bukan original. Simpan original file dengan checksum/hash bila memungkinkan, dan catat siapa, kapan, serta kamera/probe apa yang dipakai (chain of custody untuk gambar)."}]}', 480, NULL),
  (3, 'reading', 'Traceability & chain of custody', '{"slides":[{"heading":"Rantai keterunutan","body":"Traceability menghubungkan: material (heat number/MTR) -> WPS/PQR & welder ID -> weld map/joint number -> hasil VT -> NDT lain (RT/UT/PT/MT) -> disposition (accept/repair/reject) -> repair record -> re-inspection. Setiap mata rantai harus dapat ditelusuri dua arah. Weld map adalah jantung sistem: setiap joint memiliki ID unik."},{"heading":"Welder & WPS linkage","body":"Setiap weld harus tertaut ke welder/operator yang qualified (WPQ) dan WPS yang diikuti. Jika VT menemukan pola defect berulang dari satu welder, audit trail memungkinkan trending dan tindakan korektif (mis. re-qualification welder). Tanpa linkage ini, root cause analysis menjadi mustahil."},{"heading":"Repair & re-inspection loop","body":"Indikasi reject -> NCR (Non-Conformance Report) -> disposition (repair / use-as-is dengan justifikasi engineering / reject) -> repair procedure -> VT ulang pada area repair + zona sekitarnya. Re-inspection harus merujuk ke report awal (report number) agar histori lengkap terlihat. Crack dan area repair umumnya menuntut re-VT 100% dan sering ditambah NDT volumetrik (RT/UT)."},{"heading":"Kalibrasi & ketelusuran alat","body":"Gauge (bridge cam/undercut, fillet weld, Hi-Lo, taper, pit depth) dan light meter harus memiliki kalibrasi tertelusur (traceable ke standar nasional, mis. NIST atau metrologi nasional) dengan label dan tanggal due. Report mencantumkan alat, nomor seri, dan status kalibrasi. Pembacaan dari alat yang kalibrasinya kedaluwarsa membatalkan data dan menjadi temuan audit."}]}', 460, NULL),
  (4, 'reading', 'Arsip, retensi & audit readiness', '{"slides":[{"heading":"Retensi record","body":"Periode retensi ditentukan oleh code/kontrak/regulator — umumnya minimum 5 tahun, dan untuk komponen kritis (pressure vessel ASME, struktur jembatan, instalasi nuklir) dapat selama umur layanan (life-of-plant) atau lebih. Record tidak boleh dimusnahkan sebelum periode retensi habis; ini kewajiban hukum, bukan sekadar housekeeping."},{"heading":"Arsip digital vs fisik","body":"Arsip digital butuh backup redundan (aturan 3-2-1: 3 copy, 2 jenis media, 1 off-site), penamaan file konsisten, dan format tahan lama (PDF/A untuk dokumen; TIFF/JPEG untuk gambar). Tanda tangan elektronik harus memenuhi syarat keabsahan (audit log + autentikasi user). Arsip fisik butuh perlindungan dari kerusakan dan akses terkontrol."},{"heading":"Audit trail & kontrol revisi","body":"Audit trail mencatat setiap perubahan: siapa, kapan, apa yang diubah, dari nilai berapa ke berapa. Dokumen prosedur dikendalikan revisinya (revision control) — hanya revisi current yang berlaku, revisi obsolete ditarik atau ditandai jelas. Saat audit (mis. ISO 9001, klien, atau regulator), inspektur harus mampu menyajikan record lengkap dengan cepat."},{"heading":"Temuan audit yang umum","body":"Top findings: acceptance standard/edisi tidak disebut atau salah, foto tanpa skala/ID, gauge dengan kalibrasi kedaluwarsa, koreksi report memakai correction fluid atau dihapus, repair tanpa re-inspection record, dan sertifikasi inspektur yang sudah kedaluwarsa pada tanggal inspeksi. Level II bertanggung jawab mencegah semua ini sebelum sign-off."}]}', 420, NULL),
  (5, 'quiz', 'Mini-quiz — Documentation & Audit Trail', '{"description":"8 soal dokumentasi VT, standar fotografi, traceability, kalibrasi, dan audit readiness Level II.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 4 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa elemen ''scale reference'' (penggaris/gauge dalam frame) wajib ada pada foto inspeksi VT?',
   '["Agar ukuran indikasi (mis. panjang undercut) dapat dibuktikan dan direproduksi dari foto","Agar foto terlihat lebih profesional bagi klien","Karena code mewajibkan minimal dua objek dalam setiap frame","Untuk mengisi ruang kosong pada gambar"]', 0,
   'Foto inspeksi adalah bukti. Tanpa skala dalam frame, dimensi indikasi tidak dapat dibuktikan secara kuantitatif, sehingga foto tidak bisa dipakai untuk mendemonstrasikan pemenuhan atau pelanggaran acceptance limit (mis. panjang/kedalaman undercut).', 'Standar Fotografi', 'easy'),
  ('Saat melakukan koreksi pada report VT yang sudah ditulis tangan, metode yang benar dan dapat diaudit adalah:',
   '["Menghapus tulisan lama dengan correction fluid lalu tulis ulang","Menimpa angka lama dengan angka baru agar terlihat rapi","Single-line strikethrough pada data lama, tulis koreksi, beri paraf dan tanggal","Membuat report baru dan membuang report lama tanpa catatan"]', 2,
   'Audit trail menuntut data asli tetap terbaca (no obliteration). Koreksi yang sah: coret satu garis pada data lama, tulis nilai yang benar, lalu paraf dan tanggal. Correction fluid atau menimpa data menghilangkan jejak dan menjadi temuan audit.', 'Audit Trail', 'medium'),
  ('Dalam menyebut acceptance standard pada report VT, mengapa tidak cukup hanya menulis ''AWS D1.1'' tanpa edisi/clause?',
   '["Karena nama code harus selalu disingkat dalam report","Karena batas acceptance (mis. undercut) dan letak clause dapat berbeda antar edisi sehingga acuan bisa salah","Karena AWS melarang penyebutan nama code di report","Karena edisi tidak pernah memengaruhi kriteria penerimaan"]', 1,
   'Kriteria penerimaan dan lokasi clause berubah antar edisi: edisi terkini menempatkan visual acceptance di Clause 8, sedangkan edisi lama di Section 6. Menyebut edisi tahun + clause spesifik mencegah penggunaan acuan yang salah dan menahan audit.', 'Code Compliance', 'medium'),
  ('Apa yang menjadi ''jantung'' sistem traceability sehingga setiap weld dapat ditelusuri dua arah?',
   '["Daftar harga material","Jadwal shift welder","Weld map dengan joint ID unik yang menautkan welder, WPS, dan hasil inspeksi","Brosur peralatan VT"]', 2,
   'Weld map memberi ID unik untuk setiap joint dan menjadi simpul yang menautkan material/heat, welder & WPS, hasil VT/NDT lain, hingga disposition dan repair. Inilah dasar traceability dua arah.', 'Traceability', 'easy'),
  ('Sebuah indikasi crack ditemukan dan di-reject. Urutan audit trail yang benar untuk menutup temuan tersebut adalah:',
   '["Langsung tandai accept setelah welder berjanji memperbaiki","Reject -> NCR & disposition -> repair procedure -> VT ulang area repair + zona sekitar, dirujuk ke report awal","Buang report awal dan buat report baru tanpa referensi","Cukup catat di buku harian pribadi inspektur"]', 1,
   'Loop yang benar: indikasi reject memicu NCR dengan disposition, lalu repair procedure, kemudian re-VT pada area repair dan zona sekitarnya, dengan rujukan ke report awal (report number) agar histori lengkap dan tertelusur. Crack sering juga menuntut NDT volumetrik tambahan.', 'Traceability', 'hard'),
  ('Saat audit menemukan bahwa pit depth gauge yang dipakai sudah lewat tanggal kalibrasi (calibration overdue), konsekuensinya terhadap data adalah:',
   '["Data tetap valid karena alatnya masih berfungsi normal","Data dari alat tersebut dianggap tidak valid dan menjadi temuan audit; pengukuran perlu diulang dengan alat terkalibrasi","Cukup tambahkan catatan ''alat agak telat kalibrasi'' pada report","Hanya memengaruhi report Level I, bukan report Level II"]', 1,
   'Pengukuran hanya sah jika alat terkalibrasi dan tertelusur ke standar nasional dengan tanggal due yang valid. Alat overdue membuat data tidak dapat dipertanggungjawabkan, menjadi temuan audit, dan menuntut pengukuran ulang dengan alat terkalibrasi.', 'Kalibrasi & Ketelusuran', 'medium'),
  ('Untuk komponen kritis seperti pressure vessel ASME atau struktur jembatan, pendekatan retensi record inspeksi yang tepat adalah:',
   '["Boleh dimusnahkan setelah 30 hari karena konstruksi sudah selesai","Tidak perlu diarsipkan jika hasilnya accept","Retensi mengikuti code/kontrak/regulator — umumnya minimum 5 tahun, dan untuk komponen kritis bisa selama umur layanan (life-of-plant)","Disimpan inspektur secara pribadi tanpa backup"]', 2,
   'Periode retensi ditetapkan oleh code/kontrak/regulator; umumnya minimum 5 tahun dan untuk komponen kritis dapat selama umur layanan atau lebih. Memusnahkan record sebelum periode retensi habis adalah pelanggaran kewajiban hukum.', 'Arsip & Retensi', 'medium'),
  ('Manakah pengeditan gambar inspeksi yang DAPAT diterima dalam praktik audit?',
   '["Cloning untuk menghapus indikasi yang mengganggu komposisi","Mengubah contrast curve secara ekstrem agar defect terlihat lebih besar","Crop yang menghilangkan konteks weld ID dari frame","Anotasi non-destruktif (panah/kotak/skala) pada copy, dengan file original tetap tersimpan"]', 3,
   'Manipulasi yang mengubah makna (cloning, contrast ekstrem, crop yang membuang konteks) dilarang. Yang sah adalah anotasi non-destruktif pada salinan, sementara file original disimpan utuh (idealnya dengan checksum/hash) untuk menjaga integritas dan chain of custody gambar.', 'Standar Fotografi', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 5 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Struktur AWS D1.1 dan logika acceptance', '{"slides":[{"heading":"Edisi & lokasi kriteria visual","body":"AWS D1.1/D1.1M Structural Welding Code — Steel. Edisi terkini (2020, 2025) menempatkan kriteria penerimaan inspeksi visual di Clause 8 (Inspection), khususnya Table 8.1 Visual Inspection Acceptance Criteria. Edisi 2015 dan sebelumnya memakai Section 6 dengan Table 6.1 — substansi serupa, hanya penomoran berbeda. Penting: profil las (reinforcement, convexity) dirujuk dari Clause 7 (Fabrication, mis. Figure 7.4 dan Table 7.9), sedangkan limit diskontinuitas ada di Table 8.1. Saat menulis report SELALU sebut edisi spesifik (mis. ''AWS D1.1:2020, Clause 8, Table 8.1'') karena limit dapat berubah antar revisi."},{"heading":"Dua kolom besar: Statically vs Cyclically Loaded","body":"Table 8.1 membagi acceptance menjadi dua kategori sambungan nontubular: (1) Statically Loaded — beban tetap, mis. struktur gedung; (2) Cyclically Loaded — beban berulang/fatigue, mis. jembatan, crane runway, mesin. Cyclically loaded SELALU lebih ketat karena diskontinuitas kecil dapat menjadi titik inisiasi retak fatigue, terutama bila transverse (tegak lurus) terhadap tegangan tarik. Inspektur harus tahu kategori sambungan SEBELUM mengukur — baris dan limit yang dipakai berbeda."},{"heading":"Yang SELALU ditolak (zero-tolerance)","body":"Beberapa diskontinuitas ditolak tanpa memandang ukuran maupun kategori beban: (1) crack of any size/location — retak apa pun langsung reject (Crack Prohibition berlaku untuk static maupun cyclic); (2) incomplete fusion / lack of fusion; (3) incomplete penetration pada Complete Joint Penetration (CJP) groove weld; (4) overlap; (5) crater crack. Ini absolut. Tugas Level II adalah memverifikasi tidak ada item ini SEBELUM mengukur diskontinuitas yang punya limit numerik."},{"heading":"Hierarki dokumen referensi","body":"AWS D1.1 tidak berdiri sendiri. AWS A2.4 mengatur welding symbols (untuk baca drawing & tahu CJP vs PJP, leg size yang diminta). AWS A3.0 mengatur terminologi (definisi undercut, overlap, reinforcement). WPS (Welding Procedure Specification) menetapkan parameter; inspektur memverifikasi las sesuai WPS dan kriteria acceptance D1.1. Untuk pressure equipment dipakai ASME Section V Article 9 + code konstruksi terkait (mis. ASME VIII), bukan D1.1."}]}', 470, NULL),
  (2, 'reading', 'Limit numerik kunci — undercut, porosity, fusion', '{"slides":[{"heading":"Undercut — tergantung beban, arah tegangan, & tebal","body":"Statically loaded: undercut maksimum 1 mm (1/32 in) untuk material < 25 mm (1 in); untuk material >= 25 mm batasnya 2 mm (1/16 in). Cyclically loaded jauh lebih ketat: pada bagian las yang TRANSVERSE terhadap tegangan tarik (tension), undercut tidak boleh > 0.25 mm (0.01 in); untuk semua kasus lain (mis. paralel tegangan, compression) batas cyclic = 1 mm (1/32 in). Selalu ukur kedalaman dengan bridge cam / undercut gauge, bukan estimasi mata. (Catatan: draft lama menyebut threshold 6 mm dengan limit 0.5 mm — itu KELIRU; threshold D1.1 adalah 25 mm.)"},{"heading":"Porosity (visual surface)","body":"CJP groove weld cyclically loaded transverse terhadap tension: TIDAK boleh ada visible piping porosity (zero). Statically loaded (fillet & groove): frekuensi maks satu pori per 100 mm (4 in) panjang dengan diameter maksimum 2.5 mm (3/32 in); ada pula batas sumasi (jumlah pori diameter >= 1 mm dalam tiap 25 mm tidak melebihi nilai tabel). Ingat: VT hanya menilai porositas PERMUKAAN; porositas internal urusan RT/UT."},{"heading":"Fusion, penetrasi & cap defects","body":"Incomplete fusion dan incomplete penetration pada CJP = reject mutlak. Overlap (cold lap di toe) = reject karena tidak ada fusi dan menciptakan notch tajam — ini zero-tolerance, bukan limit numerik. Pada PJP, kedalaman penetrasi efektif harus memenuhi yang disyaratkan drawing (lewat WPS), diverifikasi pada las macro/qualification. Crater yang tidak terisi (underfilled crater) yang membuat ukuran las kurang dari spec juga ditolak."},{"heading":"Weld size & underrun (undersize)","body":"Fillet weld leg/throat tidak boleh kurang dari ukuran yang ditentukan drawing, KECUALI dalam toleransi undersize D1.1. Undersize (U) yang diizinkan bergantung ukuran nominal (S): S = 3–5 mm (1/8–3/16 in) → U <= 2 mm (1/16 in); S = 6 mm (1/4 in) → U <= 2.5 mm (3/32 in); S >= 8 mm (5/16 in) → U <= 3 mm (1/8 in). SYARAT: total panjang bagian undersize tidak melebihi 10% panjang las. Ukur leg dengan fillet weld gauge, bukan penggaris biasa."}]}', 510, NULL),
  (3, 'reading', 'Weld profile & convexity/concavity', '{"slides":[{"heading":"Reinforcement groove weld (butt)","body":"Groove weld butt joint minimal terisi rata (flush) atau sedikit cembung — tidak boleh underfill. Reinforcement maksimum (Table 7.9) bergantung tebal: t <= 25 mm → maks 3 mm (1/8 in); t > 25 sampai 50 mm → maks 5 mm (3/16 in); t > 50 mm → maks 6 mm (1/4 in), tetapi untuk struktur cyclically loaded maks 5 mm (3/16 in). Reinforcement berlebih menciptakan stress concentration di toe — kritis untuk cyclically loaded di mana toe sering harus di-grind dan blend mulus agar lolos fatigue. Transisi toe harus gradual; overlap tidak diizinkan."},{"heading":"Fillet weld — convexity limit","body":"Fillet weld boleh cembung (convex), tetapi convexity maksimum dibatasi oleh lebar muka las / individual bead (W) per Table 7.9: W <= 8 mm (5/16 in) → maks 2 mm (1/16 in); W > 8 mm sampai < 25 mm (1 in) → maks 3 mm (1/8 in); W >= 25 mm → maks 5 mm (3/16 in). Convexity berlebih = stress raiser. Ukur dengan fillet weld gauge. Concavity pada fillet diizinkan TANPA batas khusus ASALKAN ukuran las minimum (leg DAN throat) tetap terpenuhi; concavity yang mengurangi throat di bawah spec = reject."},{"heading":"Profil yang ditolak","body":"Profil reject menurut D1.1 (lihat Figure 7.4): insufficient throat (concave berlebih), excessive convexity, undercut di toe melebihi limit, overlap (cold lap), insufficient leg/underfill, incomplete fusion antar pass. Inspektur Level II harus mengenali profil ini secara visual lalu mengonfirmasi dengan gauge yang tepat. Hi-Lo (alignment) gauge dipakai untuk memverifikasi misalignment (high-low) pada butt joint tidak melebihi limit drawing/code."}]}', 450, NULL),
  (4, 'reading', 'Penerapan per joint type & sign-off Level II', '{"slides":[{"heading":"Alur inspeksi per joint type","body":"1) Baca welding symbol (A2.4) → tentukan tipe: CJP groove, PJP groove, atau fillet, dan ukuran yang diminta. 2) Tentukan kategori beban (static/cyclic) dan arah tegangan dari drawing/engineer. 3) Pilih baris Table 8.1 yang sesuai. 4) Verifikasi zero-tolerance items (crack, fusion, penetration, overlap). 5) Ukur diskontinuitas terukur (undercut, porosity, profile, leg) dengan gauge yang tepat dan lighting memadai (>= 1000 lux pada permukaan). 6) Bandingkan ke limit. 7) Dokumentasikan accept/reject/repair dengan referensi clause."},{"heading":"Contoh keputusan","body":"Kasus: fillet weld cyclically loaded, transverse terhadap tension, leg diminta 8 mm. Ditemukan undercut 0.3 mm pada toe. Bila statically loaded ini lolos (< 1 mm), tetapi karena cyclically loaded transverse tension limitnya 0.25 mm (0.01 in) → REJECT, perlu repair (grind & blend atau re-weld). Inilah mengapa kategori beban DAN arah tegangan harus ditetapkan dulu. Level I tidak boleh membuat sign-off final pada keputusan borderline seperti ini; Level II yang menandatangani."},{"heading":"Tanggung jawab sign-off Level II","body":"Level II berwenang menandatangani penerimaan akhir (final acceptance) dan menulis Inspection Report. Report wajib memuat: identifikasi sambungan, WPS, edisi & clause/table D1.1 yang dipakai (mis. D1.1:2020 Table 8.1), hasil ukur tiap diskontinuitas, gauge yang digunakan, kondisi lighting (>= 1000 lux), dan disposisi (accept/reject/repair). Audit trail ini bertahan untuk umur struktur. Kesalahan klasifikasi static/cyclic atau salah baris tabel adalah temuan audit serius."},{"heading":"Jembatan ke CWI","body":"Penguasaan Table 8.1 (limit undercut, porosity, convexity, reinforcement, profil reject) adalah inti ujian CWI Part B (Practical) yang memakai Book of Specifications berbasis kode (umumnya D1.1). CWI menuntut Anda menemukan baris yang benar di bawah tekanan waktu. Kuasai struktur tabel, perbedaan static/cyclic, arah tegangan, dan zero-tolerance items sebagai fondasi sebelum melangkah ke AWS QC1 CWI examination."}]}', 470, NULL),
  (5, 'quiz', 'Mini-quiz — Code Mastery AWS D1.1', '{"description":"8 soal penerapan kriteria penerimaan visual AWS D1.1 Clause 8 (Table 8.1) & profil Clause 7: undercut, porosity, convexity, reinforcement, static vs cyclic, dan zero-tolerance.","questionCount":8,"passingScore":75}', 680, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 5 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada AWS D1.1 edisi terkini (2020/2025), di mana kriteria penerimaan inspeksi visual berada?',
   '["Section 6, Table 6.1","Clause 8, Table 8.1","Annex K","Clause 4, Table 4.1"]', 1,
   'Edisi terkini AWS D1.1 menempatkan Visual Inspection Acceptance Criteria di Clause 8, Table 8.1. Edisi 2015 dan sebelumnya memakai Section 6 / Table 6.1 dengan substansi serupa. Limit profil (convexity, reinforcement) dirujuk dari Clause 7 (mis. Table 7.9, Figure 7.4).', 'Struktur Kode', 'easy'),
  ('Diskontinuitas berikut yang SELALU ditolak oleh AWS D1.1 tanpa memandang ukuran maupun kategori beban adalah:',
   '["Reinforcement setinggi 2 mm pada groove weld t = 12 mm","Crack (retak) ukuran apa pun","Convexity 2 mm pada fillet weld dengan W = 7 mm","Undercut 0.2 mm pada static compression t = 10 mm"]', 1,
   'Crack of any size/location adalah reject mutlak (Crack Prohibition, berlaku static maupun cyclic), bersama incomplete fusion, incomplete penetration pada CJP, overlap, dan crater crack. Ketiga pilihan lain berada dalam limit yang diizinkan (reinforcement <= 3 mm untuk t <= 25 mm; convexity 2 mm untuk W <= 8 mm; undercut static < 1 mm).', 'Zero-Tolerance', 'easy'),
  ('Sebuah fillet weld cyclically loaded yang transverse terhadap tegangan tarik (tension) ditemukan memiliki undercut 0.3 mm pada toe. Apa keputusan yang benar?',
   '["Accept — di bawah 1 mm sehingga selalu lolos","Accept — undercut tidak pernah jadi masalah pada fillet","Reject — limit undercut transverse-to-tension cyclically loaded adalah 0.25 mm (0.01 in)","Reject — semua undercut pada fillet weld ditolak"]', 2,
   'Pada cyclically loaded yang transverse terhadap tensile stress, undercut tidak boleh melebihi 0.25 mm (0.01 in). 0.3 mm melebihi limit ini sehingga REJECT. Pada static loaded (t < 25 mm) limitnya 1 mm, itulah mengapa kategori beban dan arah tegangan wajib ditetapkan dulu.', 'Undercut', 'medium'),
  ('Untuk sambungan statically loaded dengan tebal material kurang dari 25 mm (1 in), berapa kedalaman undercut maksimum yang diizinkan AWS D1.1?',
   '["0.25 mm (0.01 in)","1 mm (1/32 in)","3 mm (1/8 in)","Tidak ada undercut yang diizinkan"]', 1,
   'Statically loaded untuk material < 25 mm mengizinkan undercut maksimum 1 mm (1/32 in); untuk material >= 25 mm batasnya 2 mm (1/16 in). Bandingkan dengan cyclically loaded transverse-to-tension yang hanya 0.25 mm (0.01 in). Tidak ada threshold ''6 mm'' di D1.1.', 'Undercut', 'medium'),
  ('Mengapa kriteria penerimaan untuk sambungan cyclically loaded lebih ketat daripada statically loaded?',
   '["Karena las cyclically loaded selalu lebih tebal","Karena diskontinuitas kecil dapat menjadi titik inisiasi retak fatigue di bawah beban berulang","Karena cyclically loaded selalu pada material non-ferrous","Karena inspeksi cyclically loaded tidak menggunakan gauge"]', 1,
   'Beban berulang (fatigue) membuat diskontinuitas kecil seperti undercut atau notch toe menjadi titik inisiasi retak yang tumbuh hingga gagal — terutama bila transverse terhadap tegangan tarik. Karena itu limit (undercut, porositas permukaan) diperketat untuk sambungan cyclically loaded.', 'Static vs Cyclic', 'medium'),
  ('Pada fillet weld dengan lebar muka las (W) lebih besar dari 8 mm tetapi kurang dari 25 mm, berapa convexity maksimum yang diizinkan AWS D1.1 (Table 7.9)?',
   '["2 mm (1/16 in)","3 mm (1/8 in)","5 mm (3/16 in)","Tidak ada batas convexity"]', 1,
   'D1.1 membatasi convexity fillet berdasarkan lebar muka/bead (W): W <= 8 mm (5/16 in) → maks 2 mm (1/16 in); W > 8 hingga < 25 mm → maks 3 mm (1/8 in); W >= 25 mm → maks 5 mm (3/16 in). Convexity berlebih menjadi stress raiser di toe.', 'Weld Profile', 'hard'),
  ('Mengapa overlap (cold lap) di toe las selalu ditolak menurut AWS D1.1, berapa pun ukurannya?',
   '["Karena menambah tinggi reinforcement melebihi 3 mm","Karena merupakan logam tanpa fusi yang menciptakan notch tajam (stress raiser)","Karena selalu disertai porositas internal","Karena membuat throat menjadi terlalu tebal"]', 1,
   'Overlap adalah logam las yang meluap ke base metal tanpa fusi, menciptakan notch/celah tajam di toe yang bertindak sebagai stress concentration dan titik inisiasi retak. Karena tidak ada fusi, ini reject zero-tolerance tanpa limit ukuran.', 'Weld Profile', 'hard'),
  ('Sebuah fillet weld dengan ukuran nominal (S) yang diminta 8 mm ditemukan undersize. Menurut toleransi undersize D1.1, agar tetap acceptable berapa kekurangan (U) maksimum dan syaratnya?',
   '["U <= 3 mm (1/8 in), asalkan total panjang undersize <= 10% panjang las","U <= 0.25 mm, tanpa batas panjang","U <= 5 mm, asalkan tidak pada ujung las","Tidak ada undersize yang diizinkan; harus persis 8 mm"]', 0,
   'Untuk S >= 8 mm (5/16 in), undersize (U) yang diizinkan adalah <= 3 mm (1/8 in), DENGAN syarat total panjang bagian undersize tidak melebihi 10% panjang las. Untuk S lebih kecil, U yang diizinkan lebih kecil (mis. S = 3–5 mm → U <= 2 mm; S = 6 mm → U <= 2.5 mm).', 'Weld Size', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 6 — CWI Pathway (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'CWI — apa itu dan kenapa VT Level II penting', '{"slides":[{"heading":"Apa itu CWI","body":"AWS Certified Welding Inspector (CWI) adalah sertifikasi inspeksi las paling diakui di industri, dikelola American Welding Society di bawah dokumen AWS QC1 (Specification for AWS Certification of Welding Inspectors). CWI bukan sertifikasi NDT-method seperti VT/UT/RT; ia adalah sertifikasi peran inspektur las yang menggabungkan visual inspection, pengetahuan welding process, metallurgy, code interpretation, dan dokumentasi. Sertifikasi diperbarui (renew) pada tahun ke-3 dan ke-6, lalu recertification penuh pada tahun ke-9 (lewat 80 PDH continuing education, sertifikasi AWS tambahan, atau re-exam)."},{"heading":"Hubungan VT Level II dengan CWI","body":"VT adalah fondasi praktis CWI: mayoritas pekerjaan harian CWI adalah visual examination las. VT Level II memberi kompetensi teknik VT (pencahayaan minimum 1000 lux / 100 fc pada permukaan, jarak mata <=600 mm / 24 in, sudut pandang >=30 deg), penggunaan gauge profil las, dan interpretasi kriteria penerimaan — semua skill yang langsung diuji di CWI Part B (Practical). Banyak employer mensyaratkan atau sangat memilih kandidat dengan VT Level II sebelum mensponsori CWI."},{"heading":"CWI bukan pengganti VT Level II","body":"Penting dipahami: CWI dan VT Level II adalah skema berbeda di bawah dokumen berbeda (AWS QC1 vs SNT-TC-1A/CP-189). Memegang CWI tidak otomatis memberi sertifikat VT Level II per SNT-TC-1A, dan sebaliknya. Namun keduanya saling memperkuat: VT Level II = kompetensi metode visual; CWI = otoritas inspektur las dengan code mastery. Jalur karier umum: VT-L1 -> VT-L2 -> CWI -> SCWI/CWE."},{"heading":"Nilai karier","body":"Kompensasi CWI biasanya lebih tinggi dibanding inspektur VT murni karena cakupan tanggung jawab lebih luas (pemahaman WPS/PQR, sign-off laporan, mentor, audit program). CWI membuka jalur ke fabrikasi struktural (AWS D1.1), pipeline (API 1104), dan boiler/pressure vessel (ASME). VT Level II adalah batu loncatan praktis terbaik menuju CWI karena pengalaman inspeksi visualnya dapat dihitung sebagai pengalaman yang relevan untuk eligibilitas CWI."}]}', 440, NULL),
  (2, 'reading', 'Struktur ujian CWI — tiga bagian', '{"slides":[{"heading":"Part A — Fundamentals (closed book)","body":"Ujian closed-book berisi ~150 soal pilihan ganda, durasi ~2 jam, tentang prinsip dasar: welding process (SMAW, GMAW, FCAW, GTAW, SAW), simbol las dasar, definisi cacat/discontinuity, metallurgy dasar, heat treatment, distorsi, safety, perhitungan dasar, dan prinsip pengujian destruktif/non-destruktif. Bagian ini sering paling menantang bagi inspektur VT karena keluar dari zona nyaman visual ke proses & metalurgi."},{"heading":"Part B — Practical (open book, Book of Specifications)","body":"Ujian praktik ~2 jam, ~46 soal, menggunakan ''Book of Specifications'' khusus AWS (bukan code asli) + replica weld specimen plastik dan alat ukur (mis. fillet weld gauge, undercut/bridge cam gauge, mistar). Kandidat mengukur profil las nyata — reinforcement, undercut, overlap, leg & throat — lalu menilai terima/tolak terhadap kriteria di Book of Specifications. Inilah bagian yang paling bergantung pada skill pengukuran VT Level II."},{"heading":"Part C — Code Book (open book)","body":"Ujian open-book menggunakan satu code yang dipilih kandidat — paling umum AWS D1.1 (Structural Welding Code — Steel), alternatif API 1104 atau ASME Section IX. Sekitar 46-60 soal; kandidat menavigasi code untuk menemukan acceptance criteria, kualifikasi prosedur (WPS/PQR), dan persyaratan inspeksi. Menguji kecepatan dan ketepatan membaca code di bawah tekanan waktu."},{"heading":"Persyaratan kelulusan & vision","body":"Ketiga bagian (A, B, C) harus dilulusi masing-masing dengan skor minimal 72%. Jika satu bagian gagal, hanya bagian itu yang perlu diulang (dalam jendela waktu retest yang ditentukan). Syarat penglihatan CWI per AWS QC1: near-vision Jaeger J2 (atau setara) pada jarak >=30 cm (12 in), plus tes persepsi/diferensiasi warna; pemeriksaan dilakukan tidak lebih dari 1 tahun sebelum ujian — sama dengan disiplin persyaratan VT yang sudah dikuasai di Level II."}]}', 480, NULL),
  (3, 'reading', 'Dokumen AWS kunci — QC1, A2.4, A3.0', '{"slides":[{"heading":"AWS QC1 — aturan main sertifikasi","body":"AWS QC1 (Specification for AWS Certification of Welding Inspectors) mendefinisikan kategori (CAWI, CWI, SCWI), syarat pendidikan + pengalaman, persyaratan penglihatan, struktur ujian, masa berlaku, renewal, dan recertification. Tiga level: CAWI (Certified Associate WI — entry, kewenangan terbatas, bekerja di bawah supervisi CWI), CWI (full inspector authority), dan SCWI (Senior CWI — dapat mengaudit dan mensupervisi program inspeksi). VT Level II paling selaras dengan jalur CWI penuh."},{"heading":"AWS A2.4 — simbol las (welding symbols)","body":"AWS A2.4 (Standard Symbols for Welding, Brazing, and Nondestructive Examination) adalah bahasa grafis di drawing. Inspektur harus membaca elemen: reference line, arrow side vs other side, weld symbol (fillet, groove, plug), ukuran leg/throat, panjang & pitch (intermittent), contour/finish symbol, field weld flag, weld-all-around. A2.4 juga memuat simbol NDE (VT, UT, RT, MT, PT, ET) yang ditempatkan pada tail simbol — krusial untuk menentukan metode pemeriksaan yang diminta pada sambungan tertentu."},{"heading":"AWS A3.0 — terminologi las","body":"AWS A3.0 (Standard Welding Terms and Definitions) adalah kamus resmi. Membedakan istilah yang sering tertukar: discontinuity (ketidaksinambungan, belum tentu reject) vs defect (discontinuity yang melebihi kriteria penerimaan, harus reject/rejectable); fusion vs penetration; root vs face vs toe; reinforcement vs convexity. Laporan dan jawaban ujian CWI harus memakai terminologi A3.0 yang tepat — salah istilah dapat membatalkan validitas laporan inspeksi."},{"heading":"Ekosistem dokumen pendukung","body":"Selain QC1/A2.4/A3.0, CWI bersinggungan dengan: AWS D1.1 (acceptance criteria struktural baja), AWS B1.10 (Guide for NDE of Welds), AWS B1.11 (Guide for Visual Examination of Welds — referensi langsung untuk teknik VT), serta WPS/PQR per ASME Section IX atau D1.1. VT Level II yang sudah memahami D1.1 dan teknik VT memiliki keunggulan signifikan menavigasi ekosistem dokumen ini."}]}', 500, NULL),
  (4, 'reading', 'Persiapan & transisi dari VT Level II ke CWI', '{"slides":[{"heading":"Syarat eligibilitas pengalaman","body":"AWS QC1 menggabungkan pendidikan + pengalaman welding inspection. Pendidikan teknik yang lebih tinggi menurunkan jam/tahun pengalaman yang dibutuhkan, sedangkan tanpa gelar membutuhkan pengalaman lebih banyak (umumnya beberapa tahun pekerjaan inspeksi las). Jam dan tahun pengalaman sebagai VT Level II dapat dihitung sebagai pengalaman inspeksi las relevan untuk memenuhi syarat eligibilitas CWI — selalu cek matriks eligibilitas QC1 edisi terkini."},{"heading":"Memanfaatkan skill VT Level II","body":"Skill VT Level II yang transferabel langsung ke CWI Part B: pengukuran profil dengan undercut/bridge cam gauge (undercut, reinforcement), fillet gauge (leg & throat), Hi-Lo gauge (misalignment), pit depth gauge; setup pencahayaan minimum 1000 lux; teknik direct VT (jarak mata <=600 mm, sudut >=30 deg); dan disiplin dokumentasi/audit trail dari Module 4. Latih kecepatan & konsistensi pengukuran karena Part B dibatasi waktu (~2 jam)."},{"heading":"Strategi belajar tiap bagian","body":"Part A: kuasai welding process & metallurgy dasar (di luar zona nyaman VT) plus perhitungan dasar. Part B: drill pengukuran specimen sampai refleks, hafal cara cari kriteria di Book of Specifications. Part C: pilih D1.1 jika latar struktural; latih navigasi cepat — tandai klausul acceptance criteria visual (Clause 8 pada edisi terkini, Section 6 pada edisi lama), tabel batas undercut, dan kualifikasi prosedur. Ikuti AWS seminar pre-exam jika memungkinkan."},{"heading":"Setelah CWI — jalur lanjut","body":"Setelah CWI: dapat menjadi mentor, menandatangani laporan inspeksi, naik ke SCWI (audit & supervisi program), atau bercabang ke endorsement/code lain (API 1104, ASME). CWI juga sering menjadi prasyarat peran QA/QC lead dan welding inspection supervisor. Transisi VT Level II -> CWI adalah investasi karier dengan ROI tinggi di sektor fabrikasi, oil & gas, dan konstruksi."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — CWI Pathway', '{"description":"7 soal tentang jalur CWI: struktur ujian (Part A/B/C), dokumen AWS QC1/A2.4/A3.0, persyaratan kelulusan & penglihatan, dan hubungan dengan VT Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 6 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dokumen AWS manakah yang mengatur skema sertifikasi Certified Welding Inspector (kategori CAWI/CWI/SCWI, syarat pengalaman, struktur ujian, dan recertification)?',
   '["AWS A2.4","AWS QC1","AWS A3.0","AWS D1.1"]', 1,
   'AWS QC1 (Specification for AWS Certification of Welding Inspectors) mendefinisikan kategori CAWI/CWI/SCWI, syarat pendidikan+pengalaman, persyaratan penglihatan, dan struktur ujian. A2.4 = simbol las, A3.0 = terminologi, D1.1 = code struktural baja.', 'CWI Pathway', 'easy'),
  ('Ujian CWI terdiri dari tiga bagian. Bagian manakah yang paling bergantung pada skill VT Level II karena mengharuskan kandidat mengukur profil las nyata (undercut, reinforcement, leg/throat) pada replica specimen menggunakan gauge?',
   '["Part A — Fundamentals","Part C — Code Book","Part B — Practical","Part D — Metallurgy"]', 2,
   'Part B (Practical) menggunakan replica weld specimen plastik, alat ukur (fillet/undercut gauge, mistar), dan Book of Specifications; kandidat mengukur profil las dan menilai terima/tolak — langsung memanfaatkan skill pengukuran VT Level II. Tidak ada ''Part D'' pada ujian CWI.', 'CWI Pathway', 'medium'),
  ('Pada ujian CWI, Part A (Fundamentals) dan Part C (Code Book) berbeda dalam hal akses materi. Pernyataan mana yang benar?',
   '["Part A closed-book, Part C open-book (menggunakan code pilihan)","Part A open-book, Part C closed-book","Keduanya closed-book","Keduanya open-book"]', 0,
   'Part A (Fundamentals) bersifat closed-book menguji prinsip dasar. Part C (Code Book) bersifat open-book di mana kandidat menavigasi code pilihannya (umumnya AWS D1.1) untuk menemukan acceptance criteria. Part B juga open-book menggunakan Book of Specifications.', 'CWI Pathway', 'medium'),
  ('Menurut terminologi AWS A3.0, apa perbedaan antara ''discontinuity'' dan ''defect''?',
   '["Keduanya identik dan dapat dipertukarkan","Discontinuity selalu harus ditolak, sedangkan defect boleh diterima","Defect hanya ada di permukaan, discontinuity hanya di bawah permukaan","Discontinuity adalah ketidaksinambungan yang belum tentu reject; defect adalah discontinuity yang melebihi kriteria penerimaan sehingga harus ditolak (rejectable)"]', 3,
   'Per AWS A3.0, discontinuity adalah interupsi pada struktur normal yang belum tentu reject; defect adalah discontinuity yang melebihi kriteria penerimaan code sehingga rejectable. Penggunaan istilah yang tepat penting untuk validitas laporan CWI.', 'Terminology', 'medium'),
  ('Menurut AWS QC1, berapa skor minimal yang harus dicapai pada SETIAP bagian (Part A, B, dan C) ujian CWI untuk memperoleh sertifikasi?',
   '["60% pada setiap bagian","72% pada setiap bagian","80% pada setiap bagian","Cukup 72% rata-rata gabungan, satu bagian boleh di bawah itu"]', 1,
   'AWS QC1 mensyaratkan skor minimal 72% pada masing-masing dari ketiga bagian (Part A, B, C). Tidak ada mekanisme ''rata-rata gabungan'' yang menutupi bagian yang gagal; jika satu bagian gagal, hanya bagian itu yang perlu diulang dalam jendela waktu retest yang ditentukan.', 'CWI Pathway', 'hard'),
  ('Apa fungsi utama AWS A2.4 yang harus dikuasai inspektur las, termasuk untuk menentukan metode pemeriksaan pada drawing?',
   '["Mendefinisikan acceptance criteria undercut untuk baja struktural","Mengatur kualifikasi WPS dan PQR","Menyediakan standar simbol las, brazing, dan NDE (termasuk simbol VT/UT/RT pada tail) di gambar teknik","Mendefinisikan persyaratan penglihatan inspektur"]', 2,
   'AWS A2.4 (Standard Symbols for Welding, Brazing, and Nondestructive Examination) adalah bahasa grafis pada drawing: arrow/other side, ukuran weld, contour, dan simbol NDE pada tail yang menentukan metode pemeriksaan. Acceptance criteria undercut ada di D1.1; persyaratan penglihatan ada di QC1; kualifikasi WPS/PQR ada di D1.1/ASME IX.', 'Welding Symbols', 'medium'),
  ('Manakah pernyataan yang BENAR tentang hubungan VT Level II dan CWI?',
   '["Memegang CWI secara otomatis memberikan sertifikat VT Level II per SNT-TC-1A","CWI adalah level yang berada di bawah VT Level II","VT Level II dan CWI mengukur kompetensi yang persis sama sehingga salah satunya redundan","VT Level II (SNT-TC-1A/CP-189) dan CWI (AWS QC1) adalah skema berbeda namun saling memperkuat; VT Level II adalah fondasi praktis menuju CWI"]', 3,
   'VT Level II (di bawah SNT-TC-1A/CP-189) dan CWI (di bawah AWS QC1) adalah skema berbeda; memegang satu tidak otomatis memberi yang lain. Namun VT Level II memberi fondasi visual/pengukuran yang langsung dipakai di CWI Part B, sehingga keduanya saling memperkuat dalam jalur karier.', 'CWI Pathway', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — VT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
