-- VT-L2 Module 7 (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Rekap 1 — Fondasi VT Level II, RVT & alat optik', '{"slides":[{"heading":"Mengapa modul rekap ini ada","body":"Modul 7 adalah rangkuman menyeluruh seluruh silabus VT Level II sebelum Anda menghadapi ujian sertifikasi. Tujuannya menautkan kembali keenam tema inti — fondasi VT & CWI awareness, advanced optical aids/RVT, weld profile gauges, documentation & audit trail, code mastery AWS D1.1, dan CWI pathway — menjadi satu kerangka berpikir inspektur. Practice exam 25 soal di akhir modul ini menguji integrasi lintas-topik, bukan hafalan terpisah. Bacalah ketiga slide rekap, lalu kerjakan ujian latihan untuk mengukur kesiapan."},{"heading":"Fondasi VT yang tetap menjadi acuan","body":"Semua teknik lanjutan tetap berpijak pada parameter dasar. Direct VT: mata berada <=600 mm (24 in) dari permukaan, sudut pandang minimal >=30 derajat, dan iluminasi minimum >=1000 lux (100 fc) pada area of interest. Syarat penglihatan inspektur: near-vision acuity Jaeger J1/J2 pada jarak >=30 cm, diperiksa tahunan (annual), ditambah tes diferensiasi/persepsi warna. Standar rujukan: ASME Section V Article 9 dan ISO 17637 untuk teknik VT umum; AWS D1.1, A2.4 (welding symbols), A3.0 (terminology), dan QC1 (CWI) untuk konteks inspeksi las struktural."},{"heading":"Tiga keluarga optical aid (Modul 2)","body":"Bila akses fisik tidak memungkinkan, Level II beralih ke Remote Visual Testing (RVT). Tiga keluarga alat: (1) Rigid borescope — rangkaian lensa relay (rod-lens/Hopkins), kualitas gambar dan resolusi TERBAIK, hanya untuk jalur lurus. (2) Flexible fiberscope — coherent (image) fiber bundle yang dapat diartikulasikan untuk jalur berliku; serat patah menjadi titik hitam permanen dan resolusi turun seiring berkurangnya jumlah serat. (3) Video borescope (videoscope) — sensor CCD/CMOS chip-on-tip, tanpa honeycomb, mendukung perekaman dan pengukuran (comparison, stereo, 3D-phase). Pilih alat berdasarkan diameter probe, working length, FOV, depth of field, dan direction of view (0 derajat forward / 90 derajat side)."},{"heading":"Demonstrasi kesetaraan & batasan RVT","body":"Sebelum RVT menggantikan direct VT untuk keputusan keberterimaan, prosedur HARUS membuktikan resolusi setara melalui demonstrasi: artifact/karakter referensi terkecil yang relevan harus terbaca jelas pada jarak kerja maksimum, dan hasilnya dicatat (jenis alat, tip, jarak, iluminasi) sebagai audit trail. Ingat: optical aids tetap surface method — hanya mendeteksi yang terlihat di permukaan internal, tidak mengukur defek subsurface. Nilai pengukuran borescope adalah ESTIMASI; keputusan tolak/terima tetap dirujuk ke kriteria code dan, bila kritis, diverifikasi metode lain seperti UT untuk kedalaman."}]}', 480, NULL),
  (2, 'reading', 'Rekap 2 — Weld profile gauges & code mastery AWS D1.1', '{"slides":[{"heading":"Weld profile gauges (Modul 3)","body":"Bridge cam gauge (welding gauge) mengukur banyak parameter butt joint: tinggi reinforcement, kedalaman undercut, sudut bevel, dan misalignment/Hi-Lo permukaan. Fillet weld gauge membaca leg size dan menilai profil convex/concave; ingat theoretical throat = 0.707 x leg untuk fillet sama-kaki pada sambungan 90 derajat. Taper gauge (baji bertingkat) mengukur root gap saat fit-up dan lebar celah — fit-up yang salah adalah penyebab utama incomplete penetration/lack of fusion. Pit depth gauge mengukur kedalaman pitting; Hi-Lo gauge mengukur misalignment. Bersihkan spatter/slag dulu (terak menaikkan pembacaan reinforcement secara palsu), verifikasi alat, dan catat ID alat."},{"heading":"Struktur acceptance AWS D1.1 (Modul 5)","body":"AWS D1.1/D1.1M Structural Welding Code — Steel menempatkan kriteria penerimaan visual di Clause 8 (Table 8.1) pada edisi terkini, dan di Section 6 (Table 6.1) pada edisi lama; limit profil (convexity, reinforcement) dirujuk dari Clause 7 (mis. Table 7.9, Figure 7.4). Table 8.1 membagi sambungan menjadi Statically Loaded dan Cyclically Loaded — kategori cyclic SELALU lebih ketat karena diskontinuitas kecil menjadi titik inisiasi retak fatigue, terutama bila transverse terhadap tegangan tarik. Tetapkan tipe sambungan (CJP/PJP/fillet via A2.4), kategori beban, dan arah tegangan SEBELUM memilih baris tabel."},{"heading":"Zero-tolerance & limit numerik kunci","body":"Selalu reject tanpa memandang ukuran: crack apa pun, incomplete/lack of fusion, incomplete penetration pada CJP, overlap (cold lap = notch tajam tanpa fusi), dan crater crack. Limit terukur: undercut statically loaded <=1 mm (1/32 in) untuk material <25 mm dan <=2 mm (1/16 in) untuk >=25 mm; cyclically loaded transverse-to-tension <=0.25 mm (0.01 in). Reinforcement groove (Table 7.9) maks 3 mm untuk t<=25 mm. Convexity fillet dibatasi lebar muka W: W<=8 mm -> 2 mm; W>8 hingga <25 mm -> 3 mm; W>=25 mm -> 5 mm. Undersize fillet diizinkan terbatas asalkan total panjang undersize tidak melebihi 10% panjang las."},{"heading":"Alur keputusan inspeksi per joint","body":"Urutan inspeksi Level II: (1) baca welding symbol (A2.4) untuk tipe & ukuran las; (2) tentukan kategori beban & arah tegangan dari drawing; (3) pilih baris Table 8.1 yang sesuai; (4) verifikasi item zero-tolerance lebih dulu; (5) ukur diskontinuitas terukur dengan gauge yang tepat dan iluminasi >=1000 lux; (6) bandingkan ke limit; (7) dokumentasikan accept/reject/repair dengan rujukan edisi+clause. Kesalahan klasifikasi static/cyclic atau salah baris tabel adalah temuan audit serius — dan persis inti yang diuji pada CWI Part B & Part C."}]}', 510, NULL),
  (3, 'reading', 'Rekap 3 — Dokumentasi, audit trail & jalur CWI', '{"slides":[{"heading":"Dokumentasi sebagai bukti (Modul 4)","body":"Di Level II, output utama VT adalah dokumen inspeksi yang traceable dan tahan audit — prinsipnya: jika tidak terdokumentasi, dianggap tidak pernah dilakukan. Konten minimum report: identifikasi komponen & weld ID, prosedur + revisi, teknik (direct/remote + jenis optical aid), kondisi pencahayaan, jarak & sudut untuk direct VT, acceptance standard dengan EDISI & CLAUSE spesifik (bukan sekadar ''AWS D1.1''), hasil per indikasi, alat + status kalibrasi, sertifikasi inspektur (level + tanggal kedaluwarsa), tanggal, dan disposition. Level II berwenang menandatangani final acceptance dan menyetujui report Level I."},{"heading":"Fotografi, traceability & integritas","body":"Foto inspeksi adalah bukti: wajib ada scale reference dalam frame, label weld ID + tanggal, dan orientasi; pakai oblique/grazing light untuk menonjolkan profil dan hindari hotspot. Koreksi report: single-line strikethrough + paraf + tanggal (no obliteration, tidak boleh correction fluid). Traceability menautkan material/heat -> WPS/welder ID -> weld map (joint ID unik) -> hasil VT/NDT -> disposition -> repair -> re-inspection. Indikasi reject memicu NCR -> disposition -> repair -> re-VT area repair + zona sekitar, dirujuk ke report awal. Gauge & light meter harus kalibrasi tertelusur; alat overdue membatalkan data."},{"heading":"CWI pathway (Modul 1 awareness & Modul 6)","body":"AWS Certified Welding Inspector (CWI) dikelola di bawah AWS QC1 — skema berbeda dari VT Level II (SNT-TC-1A/CP-189), tetapi saling memperkuat: VT Level II adalah fondasi praktis menuju CWI. Tiga kategori: CAWI, CWI, SCWI. Ujian tiga bagian: Part A Fundamentals (closed-book, prinsip & metallurgy), Part B Practical (open-book Book of Specifications + pengukuran specimen — langsung memakai skill gauge VT Level II), dan Part C Code Book (open-book, umumnya AWS D1.1). Lulus butuh minimal 72% pada SETIAP bagian. Syarat penglihatan CWI: near-vision Jaeger J2 pada >=30 cm + tes warna, diperiksa dalam 1 tahun sebelum ujian."},{"heading":"Dokumen AWS & kesiapan ujian","body":"Kuasai ekosistem dokumen: QC1 (aturan sertifikasi), A2.4 (welding symbols termasuk simbol NDE pada tail), A3.0 (terminologi — bedakan discontinuity yang belum tentu reject dari defect yang melebihi kriteria sehingga rejectable), dan D1.1 (acceptance). Untuk ujian latihan 25 soal berikut: integrasikan pemilihan optical aid + pengukuran gauge + penerapan Table 8.1 + disiplin dokumentasi + konsep CWI. Kerjakan tanpa membuka catatan untuk simulasi kondisi ujian; target lulus >=75%. Fokus pada soal yang menuntut keputusan accept/reject berbasis kategori beban dan arah tegangan, karena di situlah kesalahan paling sering terjadi."}]}', 470, NULL),
  (4, 'quiz', 'PRACTICE EXAM — VT Level II (25 soal)', '{"description":"Ujian latihan menyeluruh VT Level II — 25 soal lintas-topik: advanced optical aids/RVT, weld profile gauges, documentation & audit trail, code mastery AWS D1.1, dan CWI pathway. Simulasikan kondisi ujian: kerjakan tanpa catatan, target lulus >=75%.","questionCount":25,"passingScore":75}', 2700, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 7 mini-quiz (25 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada direct VT, kombinasi parameter minimum yang benar untuk jarak mata, sudut pandang, dan iluminasi pada area of interest adalah:',
   '["Mata <=300 mm, sudut >=45 derajat, iluminasi >=500 lux","Mata <=600 mm (24 in), sudut >=30 derajat, iluminasi >=1000 lux (100 fc)","Mata <=1000 mm, sudut >=15 derajat, iluminasi >=300 lux","Mata <=600 mm, sudut >=60 derajat, iluminasi >=2000 lux"]', 1,
   'Aturan dasar direct VT: mata dalam jarak <=600 mm (24 in) dari permukaan, sudut pandang minimal >=30 derajat, dan iluminasi minimum >=1000 lux (100 fc) pada area of interest. Parameter ini tetap menjadi acuan bahkan saat menggunakan optical aids.', 'Fondasi VT', 'easy'),
  ('Persyaratan pemeriksaan penglihatan dekat (near-vision) yang benar untuk inspektur VT adalah:',
   '["Snellen 20/20 jarak jauh, diperiksa lima tahunan","Hanya tes buta warna sekali seumur hidup","Jaeger J1/J2 pada jarak >=30 cm, diperiksa tahunan, plus tes diferensiasi warna","Jaeger J5 pada jarak 1 m tanpa tes warna"]', 2,
   'Inspektur wajib lulus near-vision acuity Jaeger J1/J2 pada jarak >=30 cm yang diperiksa setiap tahun (annual), ditambah tes diferensiasi/persepsi warna. Ini berlaku untuk VT dan menjadi disiplin yang sama pada syarat penglihatan CWI.', 'Fondasi VT', 'easy'),
  ('Di antara ketiga keluarga optical aid, manakah yang memberikan kualitas gambar dan resolusi TERBAIK namun hanya dapat digunakan pada jalur akses lurus?',
   '["Flexible fiberscope dengan articulation 180 derajat","Video borescope dengan tip side-view","Rigid borescope (rod-lens/Hopkins)","Fiberscope mikro berdiameter 2.4 mm"]', 2,
   'Rigid borescope memakai rangkaian lensa relay (rod-lens/Hopkins) tanpa serat penghantar citra sehingga tidak ada honeycomb dan resolusinya tertinggi. Konsekuensinya tabung kaku hanya menjangkau jalur lurus.', 'Optical Aids', 'easy'),
  ('Citra utuh dapat dihantar dari ujung distal fiberscope ke pengamat karena adanya komponen apa?',
   '["Coherent (image) fiber bundle yang posisi relatif tiap seratnya identik di kedua ujung","Incoherent bundle yang khusus menghantar cahaya","Sensor CMOS yang dipasang di ujung tip","Rangkaian lensa relay rod-lens"]', 0,
   'Coherent/image bundle menjaga posisi relatif tiap serat identik di kedua ujung sehingga citra tersusun utuh. Incoherent bundle hanya menghantar cahaya; sensor CMOS dan rod-lens adalah ciri videoscope dan rigid borescope.', 'Optical Aids', 'medium'),
  ('Metode pengukuran videoscope yang menggunakan dua sudut pandang dari tip optik khusus untuk menghitung dimensi 3D indikasi melalui parallax disebut:',
   '["Comparison (shadow) measurement","Direction-of-view calibration","Stereo measurement","Demonstrasi resolusi"]', 2,
   'Stereo measurement memakai tip optik yang menghasilkan dua perspektif sehingga sistem menghitung koordinat 3D lewat parallax — paling akurat untuk panjang/kedalaman/luas. Comparison measurement hanya membandingkan terhadap objek referensi pada bidang yang sama dan kurang akurat.', 'Measurement', 'medium'),
  ('Sebelum RVT (remote visual testing) boleh menggantikan direct VT untuk keputusan keberterimaan menurut ASME V Article 9 / ISO 17637, langkah verifikasi yang harus dilakukan dan dicatat adalah:',
   '["Demonstrasi resolusi: artifact/karakter referensi terkecil harus terbaca jelas pada jarak kerja maksimum","Memastikan probe berdiameter di bawah 2.4 mm","Menyetel FOV ke 120 derajat","Mengganti light source ke halogen"]', 0,
   'Standar menuntut bukti kesetaraan: sistem harus mampu menampilkan artifact referensi terkecil yang relevan pada jarak kerja maksimum. Jenis alat, tip, jarak, iluminasi, dan hasil dicatat sebagai audit trail. RVT harus mendemonstrasikan resolusi setara direct VT.', 'Procedure', 'hard'),
  ('Munculnya titik-titik hitam permanen pada gambar fiberscope yang jumlahnya bertambah seiring usia dan penekukan alat paling tepat dijelaskan oleh:',
   '["Serat optik dalam image bundle yang patah/mati","Iluminasi yang melebihi 1000 lux","Sensor CCD dengan piksel mati","Articulation yang dipakai melebihi 90 derajat"]', 0,
   'Setiap serat yang patah dalam coherent bundle menjadi titik hitam permanen pada citra dan jumlahnya bertambah karena penekukan/usia. Fiberscope dengan terlalu banyak serat mati harus dipensiunkan. Videoscope tidak memakai fiber untuk menghantar citra sehingga tidak menunjukkan gejala ini.', 'Equipment Maintenance', 'medium'),
  ('Untuk menginspeksi dinding ID (internal diameter) pipa atau akar las internal di sepanjang sisi bore, direction of view (DOV) tip yang paling sesuai adalah:',
   '["Forward view 0 derajat","Side view 90 derajat","Open lens tanpa tip","Retro view ke arah operator"]', 1,
   'Side view 90 derajat mengarahkan pandangan tegak lurus ke dinding ID sehingga ideal untuk memeriksa permukaan samping bore dan akar las internal. Forward view 0 derajat cocok untuk navigasi maju dan inspeksi ujung lubang.', 'Optical Aids', 'medium'),
  ('Pernyataan yang BENAR mengenai keterbatasan optical aids (RVT) sebagai metode inspeksi adalah:',
   '["Dapat mengukur kedalaman defek subsurface secara langsung","Tetap merupakan surface method; hanya mendeteksi yang terlihat di permukaan internal","Menggantikan kebutuhan iluminasi karena memiliki cahaya sendiri tanpa batas minimum","Nilai pengukurannya bersifat absolut sehingga tidak perlu dirujuk ke code"]', 1,
   'Optical aids memperluas akses tetapi tetap surface method — hanya mendeteksi indikasi permukaan internal, bukan defek subsurface. Iluminasi memadai tetap diperlukan, dan nilai pengukuran adalah estimasi yang harus dirujuk ke kriteria code.', 'Optical Aids', 'medium'),
  ('Pada bridge cam gauge, parameter manakah yang TIDAK dapat diukur langsung oleh satu alat tersebut?',
   '["Tinggi reinforcement (cap height) pada butt weld","Kedalaman undercut pada toe las","Kandungan porositas internal di bawah permukaan","Sudut preparasi bevel groove"]', 2,
   'Bridge cam gauge mengukur dimensi permukaan: reinforcement, undercut, sudut bevel, dan misalignment. Porositas internal/subsurface tidak terukur secara visual/mekanis dan memerlukan metode volumetrik seperti RT atau UT.', 'Weld Profile Gauges', 'easy'),
  ('Untuk fillet weld sama-kaki pada sambungan 90 derajat dengan leg 10 mm, theoretical throat-nya kira-kira:',
   '["5 mm","7.07 mm","10 mm","14.14 mm"]', 1,
   'Theoretical throat = 0.707 x leg. Untuk leg 10 mm: 0.707 x 10 = 7.07 mm. Throat menentukan kapasitas beban sambungan fillet, sedangkan gauge umumnya membaca leg.', 'Weld Profile Gauges', 'medium'),
  ('Sisa terak (slag) yang tidak dibersihkan pada puncak cap saat mengukur reinforcement dengan bridge cam gauge akan menyebabkan:',
   '["Pembacaan reinforcement yang lebih tinggi secara palsu (overestimate)","Pembacaan reinforcement yang lebih rendah secara palsu","Tidak ada pengaruh karena pointer menembus terak","Hanya pengukuran sudut bevel yang menjadi tidak akurat"]', 0,
   'Terak menambah ketinggian palsu di puncak cap sehingga pointer berhenti lebih tinggi, menghasilkan reinforcement yang overestimate. Permukaan harus bersih dari spatter dan slag sebelum pengukuran dimensi apa pun.', 'Weld Profile Gauges', 'medium'),
  ('Sebelum pengelasan, taper gauge digunakan memverifikasi root opening sesuai WPS. Jika root gap terlalu sempit dibanding spesifikasi, risiko cacat las yang paling mungkin adalah:',
   '["Excessive reinforcement pada cap","Undercut transversal pada toe","Lack of fusion / incomplete penetration pada akar","Burn-through karena terlalu banyak panas lolos"]', 2,
   'Root gap yang terlalu sempit menyulitkan penetrasi penuh ke akar sehingga berisiko lack of fusion / incomplete penetration. Sebaliknya gap terlalu lebar berisiko burn-through. Karena itu taper gauge dipakai pada hold point fit-up.', 'Weld Profile Gauges', 'medium'),
  ('Sebuah fillet weld dengan profil sangat concave sehingga throat aktual lebih kecil dari desain. Konsekuensi utamanya adalah:',
   '["Reinforcement berlebih yang boros material","Throat efektif berkurang sehingga kapasitas menahan beban turun di bawah desain","Selalu menyebabkan overlap di toe las","Tidak masalah karena concave selalu lebih kuat dari convex"]', 1,
   'Profil concave dapat menurunkan throat efektif di bawah nilai desain sehingga kapasitas beban berkurang. Convex justru menambah material (boros) tetapi tidak mengurangi throat; overlap adalah cacat toe terpisah.', 'Weld Profile Gauges', 'medium'),
  ('Pada AWS D1.1 edisi terkini, di mana kriteria penerimaan inspeksi visual untuk diskontinuitas las berada?',
   '["Section 6, Table 6.1","Clause 8, Table 8.1","Annex K","Clause 4, Table 4.1"]', 1,
   'Edisi terkini menempatkan Visual Inspection Acceptance Criteria di Clause 8, Table 8.1. Edisi 2015 dan sebelumnya memakai Section 6 / Table 6.1. Limit profil (convexity, reinforcement) dirujuk dari Clause 7 (mis. Table 7.9, Figure 7.4).', 'Code — AWS D1.1', 'easy'),
  ('Diskontinuitas berikut yang SELALU ditolak oleh AWS D1.1 tanpa memandang ukuran maupun kategori beban adalah:',
   '["Reinforcement setinggi 2 mm pada groove weld t = 12 mm","Convexity 2 mm pada fillet weld dengan W = 7 mm","Crack (retak) ukuran apa pun","Undercut 0.2 mm pada static compression t = 10 mm"]', 2,
   'Crack of any size/location adalah reject mutlak (Crack Prohibition), bersama incomplete fusion, incomplete penetration pada CJP, overlap, dan crater crack. Tiga pilihan lain berada dalam limit yang diizinkan.', 'Code — AWS D1.1', 'easy'),
  ('Untuk sambungan statically loaded dengan tebal material kurang dari 25 mm (1 in), kedalaman undercut maksimum yang diizinkan AWS D1.1 adalah:',
   '["0.25 mm (0.01 in)","1 mm (1/32 in)","3 mm (1/8 in)","Tidak ada undercut yang diizinkan"]', 1,
   'Statically loaded untuk material < 25 mm mengizinkan undercut maksimum 1 mm (1/32 in); untuk material >= 25 mm batasnya 2 mm (1/16 in). Bandingkan dengan cyclically loaded transverse-to-tension yang hanya 0.25 mm (0.01 in).', 'Code — AWS D1.1', 'medium'),
  ('Sebuah fillet weld cyclically loaded yang transverse terhadap tegangan tarik ditemukan memiliki undercut 0.3 mm pada toe. Keputusan yang benar adalah:',
   '["Accept — di bawah 1 mm sehingga selalu lolos","Reject — limit undercut transverse-to-tension cyclically loaded adalah 0.25 mm (0.01 in)","Accept — undercut tidak pernah jadi masalah pada fillet","Reject — semua undercut pada fillet weld ditolak"]', 1,
   'Pada cyclically loaded transverse terhadap tensile stress, undercut tidak boleh melebihi 0.25 mm (0.01 in); 0.3 mm melebihi limit sehingga REJECT. Pada static loaded (t < 25 mm) limitnya 1 mm — itulah mengapa kategori beban dan arah tegangan wajib ditetapkan dulu.', 'Code — AWS D1.1', 'hard'),
  ('Pada fillet weld dengan lebar muka las (W) lebih besar dari 8 mm tetapi kurang dari 25 mm, convexity maksimum yang diizinkan AWS D1.1 (Table 7.9) adalah:',
   '["2 mm (1/16 in)","3 mm (1/8 in)","5 mm (3/16 in)","Tidak ada batas convexity"]', 1,
   'D1.1 membatasi convexity fillet berdasarkan lebar muka/bead (W): W <= 8 mm -> maks 2 mm; W > 8 hingga < 25 mm -> maks 3 mm; W >= 25 mm -> maks 5 mm. Convexity berlebih menjadi stress raiser di toe.', 'Code — AWS D1.1', 'hard'),
  ('Mengapa overlap (cold lap) di toe las selalu ditolak menurut AWS D1.1, berapa pun ukurannya?',
   '["Karena menambah tinggi reinforcement melebihi 3 mm","Karena selalu disertai porositas internal","Karena merupakan logam tanpa fusi yang menciptakan notch tajam (stress raiser)","Karena membuat throat menjadi terlalu tebal"]', 2,
   'Overlap adalah logam las yang meluap ke base metal tanpa fusi, menciptakan notch tajam di toe yang menjadi stress concentration dan titik inisiasi retak. Karena tidak ada fusi, ini reject zero-tolerance tanpa limit ukuran.', 'Code — AWS D1.1', 'medium'),
  ('Saat melakukan koreksi pada report VT tulisan tangan, metode yang benar dan dapat diaudit adalah:',
   '["Menghapus tulisan lama dengan correction fluid lalu tulis ulang","Menimpa angka lama dengan angka baru agar terlihat rapi","Single-line strikethrough pada data lama, tulis koreksi, beri paraf dan tanggal","Membuat report baru dan membuang report lama tanpa catatan"]', 2,
   'Audit trail menuntut data asli tetap terbaca (no obliteration). Koreksi yang sah: coret satu garis pada data lama, tulis nilai yang benar, lalu paraf dan tanggal. Correction fluid atau menimpa data menjadi temuan audit.', 'Documentation & Audit Trail', 'medium'),
  ('Mengapa elemen scale reference (penggaris/gauge dalam frame) wajib ada pada foto inspeksi VT?',
   '["Agar ukuran indikasi dapat dibuktikan dan direproduksi dari foto","Agar foto terlihat lebih profesional bagi klien","Karena code mewajibkan minimal dua objek dalam setiap frame","Untuk mengisi ruang kosong pada gambar"]', 0,
   'Foto inspeksi adalah bukti. Tanpa skala dalam frame, dimensi indikasi tidak dapat dibuktikan secara kuantitatif, sehingga foto tidak bisa dipakai mendemonstrasikan pemenuhan atau pelanggaran acceptance limit.', 'Documentation & Audit Trail', 'easy'),
  ('Saat audit menemukan bahwa pit depth gauge yang dipakai sudah lewat tanggal kalibrasi (overdue), konsekuensinya terhadap data adalah:',
   '["Data tetap valid karena alatnya masih berfungsi normal","Data dianggap tidak valid dan menjadi temuan audit; pengukuran perlu diulang dengan alat terkalibrasi","Cukup tambahkan catatan ''alat agak telat kalibrasi'' pada report","Hanya memengaruhi report Level I, bukan Level II"]', 1,
   'Pengukuran hanya sah jika alat terkalibrasi dan tertelusur ke standar nasional dengan tanggal due valid. Alat overdue membuat data tidak dapat dipertanggungjawabkan, menjadi temuan audit, dan menuntut pengukuran ulang.', 'Documentation & Audit Trail', 'medium'),
  ('Menurut terminologi AWS A3.0, perbedaan antara discontinuity dan defect adalah:',
   '["Keduanya identik dan dapat dipertukarkan","Discontinuity selalu harus ditolak, sedangkan defect boleh diterima","Discontinuity adalah ketidaksinambungan yang belum tentu reject; defect adalah discontinuity yang melebihi kriteria penerimaan sehingga rejectable","Defect hanya ada di permukaan, discontinuity hanya di bawah permukaan"]', 2,
   'Per AWS A3.0, discontinuity adalah interupsi pada struktur normal yang belum tentu reject; defect adalah discontinuity yang melebihi kriteria penerimaan code sehingga rejectable. Penggunaan istilah yang tepat penting untuk validitas laporan.', 'CWI Pathway', 'medium'),
  ('Pada ujian CWI, bagian manakah yang paling bergantung pada skill VT Level II karena mengharuskan kandidat mengukur profil las nyata (undercut, reinforcement, leg/throat) pada replica specimen menggunakan gauge?',
   '["Part A — Fundamentals (closed-book)","Part C — Code Book (open-book)","Part B — Practical (open-book, Book of Specifications)","Part D — Metallurgy"]', 2,
   'Part B (Practical) menggunakan replica weld specimen, gauge (fillet/undercut), dan Book of Specifications; kandidat mengukur profil las dan menilai terima/tolak — langsung memanfaatkan skill pengukuran VT Level II. Tidak ada ''Part D'' pada ujian CWI.', 'CWI Pathway', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 8 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'quiz', 'FINAL ASSESSMENT — VT Level II', '{"description":"Ujian sertifikasi VT Level II — 50 soal · 100 menit · minimal 80% lulus. Mencakup pencahayaan & akuisisi, persyaratan penglihatan, advanced optical aids/RVT, weld profile gauges, dokumentasi & audit trail, code mastery AWS D1.1, dan CWI pathway.","questionCount":50,"passingScore":80}', 6000, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 8 mini-quiz (50 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Untuk direct (langsung) visual testing, iluminasi minimum pada permukaan area of interest yang umum disyaratkan adalah:',
   '["100 lux (10 fc)","500 lux (50 fc)","1000 lux (100 fc)","5000 lux (500 fc)"]', 2,
   'Direct VT mensyaratkan iluminasi minimum 1000 lux (100 fc) pada permukaan yang diperiksa agar diskontinuitas kecil terlihat. Nilai ini juga menjadi acuan untuk fotografi inspeksi dan demonstrasi kesetaraan RVT.', 'Pencahayaan & Akuisisi', 'easy'),
  ('Persyaratan jarak mata dan sudut pandang untuk direct VT adalah:',
   '["Mata <=600 mm (24 in) dari permukaan dan sudut pandang >=30 derajat","Mata <=300 mm dan sudut pandang >=10 derajat","Mata <=1000 mm dan sudut pandang >=45 derajat","Mata bebas selama memakai kaca pembesar 10x"]', 0,
   'Direct VT menuntut mata berada dalam jarak maksimum 600 mm (24 in) dari permukaan dengan sudut pandang minimal 30 derajat terhadap permukaan. Bila tidak dapat dipenuhi, beralih ke remote VT dengan optical aid.', 'Pencahayaan & Akuisisi', 'easy'),
  ('Persyaratan ketajaman penglihatan dekat (near-vision) untuk personel VT yang umum dipakai adalah:',
   '["Membaca Jaeger J1/J2 pada jarak >=30 cm, diperiksa setiap tahun, plus kemampuan diferensiasi warna","Hanya tes buta warna sekali seumur hidup","Penglihatan jauh 6/6 tanpa tes warna","Tidak ada persyaratan penglihatan untuk Level II"]', 0,
   'Personel VT harus lolos near-vision acuity membaca Jaeger J1 atau J2 pada jarak minimal 30 cm, diperiksa minimal setahun sekali, ditambah kemampuan membedakan/menilai warna (color differentiation).', 'Sertifikasi & Penglihatan', 'easy'),
  ('Di antara ketiga keluarga optical aid, manakah yang memberikan kualitas gambar dan resolusi TERBAIK namun hanya dapat dipakai pada jalur akses lurus?',
   '["Flexible fiberscope dengan articulation 180 derajat","Rigid borescope (rod-lens/Hopkins)","Video borescope dengan tip side-view","Fiberscope mikro berdiameter 2.4 mm"]', 1,
   'Rigid borescope memakai rangkaian lensa relay (rod-lens/Hopkins) tanpa serat penghantar citra, sehingga tidak ada efek honeycomb dan resolusinya tertinggi. Konsekuensinya tabung kaku hanya bisa menjangkau jalur lurus.', 'Optical Aids & RVT', 'easy'),
  ('Pada flexible fiberscope, citra utuh dapat dihantar dari ujung distal ke pengamat karena adanya komponen:',
   '["Sensor CMOS yang dipasang di ujung tip","Rangkaian lensa relay rod-lens","Coherent (image) fiber bundle yang posisi relatif tiap seratnya identik di kedua ujung","Incoherent bundle yang khusus menghantar cahaya"]', 2,
   'Coherent/image bundle menjaga posisi relatif setiap serat identik di kedua ujung sehingga citra tersusun utuh. Incoherent bundle hanya menghantar cahaya; sensor CMOS dan rod-lens adalah ciri videoscope dan rigid borescope.', 'Optical Aids & RVT', 'medium'),
  ('Munculnya titik-titik hitam permanen pada gambar fiberscope yang jumlahnya bertambah seiring usia dan penekukan alat paling tepat dijelaskan oleh:',
   '["Iluminasi yang melebihi 1000 lux","Sensor CCD dengan piksel mati","Articulation yang dipakai melebihi 90 derajat","Serat optik dalam image bundle yang patah/mati"]', 3,
   'Setiap serat yang patah dalam coherent bundle menjadi titik hitam permanen pada citra dan jumlahnya bertambah karena penekukan/usia. Fiberscope dengan terlalu banyak serat mati harus dipensiunkan; videoscope tidak memakai fiber untuk menghantar citra.', 'Perawatan Peralatan', 'medium'),
  ('Videoscope menghasilkan kualitas citra jauh melebihi fiberscope terutama karena:',
   '["Memakai cahaya laser bukan LED","Selalu berdiameter lebih kecil","Sensor CCD/CMOS ditempatkan langsung di ujung probe (chip-on-tip) sehingga citra tidak melewati serat","Tidak memerlukan sumber cahaya eksternal"]', 2,
   'Videoscope memakai sensor CCD/CMOS chip-on-tip di ujung probe, sehingga citra tidak melewati fiber dan tidak ada efek honeycomb; resolusi mengikuti piksel sensor dan citra mudah direkam untuk audit trail.', 'Optical Aids & RVT', 'easy'),
  ('Metode pengukuran videoscope yang menggunakan dua sudut pandang dari tip optik khusus untuk menghitung dimensi 3D indikasi melalui parallax disebut:',
   '["Comparison (shadow) measurement","Direction-of-view calibration","Demonstrasi resolusi","Stereo measurement"]', 3,
   'Stereo measurement memakai tip optik yang menghasilkan dua perspektif sehingga sistem menghitung koordinat 3D lewat parallax — paling akurat untuk panjang/kedalaman/luas. Comparison measurement hanya membandingkan terhadap objek referensi pada bidang yang sama dan kurang akurat.', 'Optical Aids & RVT', 'medium'),
  ('Sebelum RVT (remote visual testing) boleh menggantikan direct VT untuk keputusan keberterimaan menurut ASME V Article 9 / ISO 17637, langkah verifikasi yang harus dilakukan dan dicatat adalah:',
   '["Memastikan probe berdiameter di bawah 2.4 mm","Menyetel FOV ke 120 derajat","Demonstrasi resolusi: artifact/karakter referensi terkecil harus terbaca jelas pada jarak kerja maksimum","Mengganti light source ke halogen"]', 2,
   'Standar menuntut bukti kesetaraan: sistem harus mampu menampilkan artifact referensi terkecil yang relevan (mis. karakter/celah kalibrasi) di jarak kerja maksimum, dengan jenis alat, tip, jarak, iluminasi, dan hasil dicatat sebagai audit trail.', 'Optical Aids & RVT', 'hard'),
  ('Untuk menginspeksi dinding ID (internal diameter) sebuah pipa atau akar las internal di sepanjang sisi bore, direction of view (DOV) tip yang paling sesuai adalah:',
   '["Forward view 0 derajat","Open lens tanpa tip","Retro view ke arah operator","Side view 90 derajat"]', 3,
   'Side view 90 derajat mengarahkan pandangan tegak lurus ke dinding ID sehingga ideal untuk memeriksa permukaan samping bore dan akar las internal. Forward view 0 derajat cocok untuk navigasi maju dan inspeksi ujung lubang.', 'Optical Aids & RVT', 'medium'),
  ('Sebuah keterbatasan fundamental yang tetap berlaku untuk semua optical aid (borescope/fiberscope/videoscope) adalah:',
   '["Hanya dapat dipakai pada material non-feromagnetik","Tetap merupakan metode permukaan — hanya mendeteksi yang terlihat di permukaan internal, bukan defek subsurface","Selalu memberi pengukuran kedalaman yang lebih akurat daripada UT","Tidak memerlukan dokumentasi karena bersifat real-time"]', 1,
   'RVT memperluas akses tetapi tetap surface method: hanya yang terlihat di permukaan yang terdeteksi. Defek subsurface dan kedalaman kritis memerlukan metode volumetrik seperti UT atau RT.', 'Optical Aids & RVT', 'easy'),
  ('Parameter pemilihan optical aid ''working length'' merujuk pada:',
   '["Diameter probe agar muat di akses port","Sudut pandang lensa (field of view)","Panjang jangkauan probe ke titik inspeksi","Rentang jarak yang tetap fokus (depth of field)"]', 2,
   'Working length adalah panjang jangkauan probe (insertion tube) ke titik inspeksi, bisa 0.3 m hingga lebih dari 30 m pada videoscope. Diameter, FOV, dan DOF adalah parameter pemilihan terpisah.', 'Optical Aids & RVT', 'medium'),
  ('Pada bridge cam gauge, parameter manakah yang TIDAK dapat diukur langsung oleh satu alat tersebut?',
   '["Kandungan porositas internal di bawah permukaan","Tinggi reinforcement (cap height) pada butt weld","Kedalaman undercut pada toe las","Sudut preparasi bevel groove"]', 0,
   'Bridge cam gauge mengukur dimensi permukaan: reinforcement, undercut, sudut bevel, dan misalignment. Porositas internal/subsurface tidak terukur secara visual/mekanis dan memerlukan metode volumetrik seperti RT atau UT.', 'Weld Profile Gauges', 'easy'),
  ('Sisa terak (slag) yang tidak dibersihkan pada puncak cap saat mengukur reinforcement dengan bridge cam gauge akan menyebabkan:',
   '["Pembacaan reinforcement yang lebih tinggi secara palsu (overestimate)","Pembacaan reinforcement yang lebih rendah secara palsu","Tidak ada pengaruh karena pointer menembus terak","Hanya pengukuran sudut bevel yang menjadi tidak akurat"]', 0,
   'Terak menambah ketinggian palsu di puncak cap sehingga pointer berhenti lebih tinggi, menghasilkan reinforcement yang overestimate. Permukaan harus bersih dari spatter dan slag sebelum pengukuran dimensi apa pun.', 'Weld Profile Gauges', 'medium'),
  ('Untuk fillet weld sama-kaki pada sambungan 90 derajat dengan leg 10 mm, theoretical throat-nya kira-kira:',
   '["5 mm","7.07 mm","10 mm","14.14 mm"]', 1,
   'Theoretical throat = 0.707 x leg. Untuk leg 10 mm: 0.707 x 10 = 7.07 mm. Throat menentukan kapasitas beban sambungan fillet, sedangkan gauge umumnya membaca leg.', 'Weld Profile Gauges', 'medium'),
  ('Seorang inspektor menemukan fillet weld dengan profil sangat concave sehingga throat aktual lebih kecil dari desain. Konsekuensi utamanya adalah:',
   '["Reinforcement berlebih yang boros material","Selalu menyebabkan overlap di toe las","Tidak masalah karena concave selalu lebih kuat dari convex","Throat efektif berkurang sehingga kapasitas menahan beban turun di bawah desain"]', 3,
   'Profil concave dapat menurunkan throat efektif di bawah nilai desain sehingga kapasitas beban berkurang. Convex justru menambah material (boros) tetapi tidak mengurangi throat; overlap adalah cacat toe terpisah.', 'Weld Profile Gauges', 'medium'),
  ('Sebelum pengelasan, taper gauge digunakan untuk memverifikasi root opening sesuai WPS. Jika root gap terlalu sempit dibanding spesifikasi, risiko cacat las yang paling mungkin adalah:',
   '["Burn-through karena terlalu banyak panas lolos","Excessive reinforcement pada cap","Lack of fusion / incomplete penetration pada akar","Undercut transversal pada toe"]', 2,
   'Root gap yang terlalu sempit menyulitkan penetrasi penuh ke akar sehingga berisiko lack of fusion / incomplete penetration. Sebaliknya, gap terlalu lebar berisiko burn-through; karena itu taper gauge dipakai pada hold point fit-up.', 'Weld Profile Gauges', 'medium'),
  ('Pada fillet weld set gauge tipe blade/wedge bertanda ukuran (3, 5, 6, 8, 10, 12 mm), tiap blade umumnya memiliki dua sisi berbeda fungsi, yaitu:',
   '["Sisi metric dan sisi imperial pada parameter yang sama","Sisi untuk undercut dan sisi untuk porositas","Sisi untuk profil convex dan sisi untuk profil concave","Sisi untuk root gap dan sisi untuk reinforcement"]', 2,
   'Setiap blade fillet gauge biasanya memiliki satu sisi untuk menilai fillet convex dan sisi lain untuk fillet concave pada ukuran nominal yang sama, sehingga inspektor dapat menentukan undersize/oversize untuk kedua profil.', 'Weld Profile Gauges', 'hard'),
  ('Untuk mengukur kedalaman korosi pitting dari permukaan referensi dalam in-service inspection (remaining wall thickness assessment), alat yang tepat adalah:',
   '["Pit depth gauge (dial/digital dengan jembatan datum)","Bridge cam gauge","Taper/wedge gauge","Fillet weld gauge"]', 0,
   'Pit depth gauge dengan jembatan datum mengukur kedalaman pit dari permukaan referensi — penting untuk penilaian sisa tebal dinding. Bridge cam untuk profil las, taper untuk celah, fillet gauge untuk leg/throat.', 'Weld Profile Gauges', 'easy'),
  ('Saat mengukur celah panas (hot joint) dengan taper gauge dan mengambil beberapa pembacaan di sepanjang root, praktik dokumentasi Level II yang paling defensible adalah:',
   '["Laporkan nilai worst case beserta ID alat dan beberapa titik pengukuran","Laporkan hanya nilai rata-rata tanpa mencatat ID alat","Ambil satu pembacaan di tengah join saja agar cepat","Tunda semua pengukuran sampai sambungan dingin total"]', 0,
   'Dokumentasi defensible memerlukan pelaporan nilai terburuk dari beberapa titik, mencantumkan ID alat untuk traceability, dan menyadari pengaruh ekspansi termal. Rata-rata tunggal atau satu titik menyembunyikan variasi gap yang kritis.', 'Weld Profile Gauges', 'hard'),
  ('Untuk memverifikasi misalignment (high-low) eksternal pada butt joint pipa atau pelat, alat yang dirancang khusus adalah:',
   '["Pit depth gauge","Fillet weld gauge","Light meter","Hi-Lo (welding alignment) gauge"]', 3,
   'Hi-Lo gauge dirancang untuk mengukur misalignment internal/eksternal pada butt joint. Untuk Hi-Lo internal akar pipa, alat Hi-Lo dedicated lebih akurat daripada bridge cam yang hanya membaca Hi-Lo permukaan.', 'Weld Profile Gauges', 'medium'),
  ('Mengapa elemen ''scale reference'' (penggaris/gauge dalam frame) wajib ada pada foto inspeksi VT?',
   '["Agar ukuran indikasi (mis. panjang undercut) dapat dibuktikan dan direproduksi dari foto","Agar foto terlihat lebih profesional bagi klien","Karena code mewajibkan minimal dua objek dalam setiap frame","Untuk mengisi ruang kosong pada gambar"]', 0,
   'Foto inspeksi adalah bukti. Tanpa skala dalam frame, dimensi indikasi tidak dapat dibuktikan secara kuantitatif, sehingga foto tidak bisa dipakai untuk mendemonstrasikan pemenuhan atau pelanggaran acceptance limit.', 'Dokumentasi & Audit Trail', 'easy'),
  ('Saat melakukan koreksi pada report VT yang ditulis tangan, metode yang benar dan dapat diaudit adalah:',
   '["Menghapus tulisan lama dengan correction fluid lalu tulis ulang","Menimpa angka lama dengan angka baru agar terlihat rapi","Membuat report baru dan membuang report lama tanpa catatan","Single-line strikethrough pada data lama, tulis koreksi, beri paraf dan tanggal"]', 3,
   'Audit trail menuntut data asli tetap terbaca (no obliteration). Koreksi yang sah: coret satu garis pada data lama, tulis nilai yang benar, lalu paraf dan tanggal. Correction fluid atau menimpa data menjadi temuan audit.', 'Dokumentasi & Audit Trail', 'medium'),
  ('Dalam menyebut acceptance standard pada report VT, mengapa tidak cukup hanya menulis ''AWS D1.1'' tanpa edisi/clause?',
   '["Karena nama code harus selalu disingkat dalam report","Karena AWS melarang penyebutan nama code di report","Karena batas acceptance (mis. undercut) dan letak clause dapat berbeda antar edisi sehingga acuan bisa salah","Karena edisi tidak pernah memengaruhi kriteria penerimaan"]', 2,
   'Kriteria penerimaan dan lokasi clause berubah antar edisi: edisi terkini menempatkan visual acceptance di Clause 8, sedangkan edisi lama di Section 6. Menyebut edisi tahun + clause spesifik mencegah penggunaan acuan yang salah dan menahan audit.', 'Dokumentasi & Audit Trail', 'medium'),
  ('Apa yang menjadi ''jantung'' sistem traceability sehingga setiap weld dapat ditelusuri dua arah?',
   '["Daftar harga material","Weld map dengan joint ID unik yang menautkan welder, WPS, dan hasil inspeksi","Jadwal shift welder","Brosur peralatan VT"]', 1,
   'Weld map memberi ID unik untuk setiap joint dan menjadi simpul yang menautkan material/heat, welder & WPS, hasil VT/NDT lain, hingga disposition dan repair. Inilah dasar traceability dua arah.', 'Dokumentasi & Audit Trail', 'easy'),
  ('Sebuah indikasi crack ditemukan dan di-reject. Urutan audit trail yang benar untuk menutup temuan tersebut adalah:',
   '["Langsung tandai accept setelah welder berjanji memperbaiki","Buang report awal dan buat report baru tanpa referensi","Cukup catat di buku harian pribadi inspektur","Reject -> NCR & disposition -> repair procedure -> VT ulang area repair + zona sekitar, dirujuk ke report awal"]', 3,
   'Loop yang benar: indikasi reject memicu NCR dengan disposition, lalu repair procedure, kemudian re-VT pada area repair dan zona sekitarnya, dengan rujukan ke report awal agar histori lengkap dan tertelusur. Crack sering juga menuntut NDT volumetrik tambahan.', 'Dokumentasi & Audit Trail', 'hard'),
  ('Saat audit menemukan bahwa pit depth gauge yang dipakai sudah lewat tanggal kalibrasi (calibration overdue), konsekuensinya terhadap data adalah:',
   '["Data tetap valid karena alatnya masih berfungsi normal","Data dari alat tersebut dianggap tidak valid dan menjadi temuan audit; pengukuran perlu diulang dengan alat terkalibrasi","Cukup tambahkan catatan ''alat agak telat kalibrasi'' pada report","Hanya memengaruhi report Level I, bukan report Level II"]', 1,
   'Pengukuran hanya sah jika alat terkalibrasi dan tertelusur ke standar nasional dengan tanggal due valid. Alat overdue membuat data tidak dapat dipertanggungjawabkan, menjadi temuan audit, dan menuntut pengukuran ulang.', 'Dokumentasi & Audit Trail', 'medium'),
  ('Manakah pengeditan gambar inspeksi yang DAPAT diterima dalam praktik audit?',
   '["Cloning untuk menghapus indikasi yang mengganggu komposisi","Mengubah contrast curve secara ekstrem agar defect terlihat lebih besar","Anotasi non-destruktif (panah/kotak/skala) pada copy, dengan file original tetap tersimpan","Crop yang menghilangkan konteks weld ID dari frame"]', 2,
   'Manipulasi yang mengubah makna (cloning, contrast ekstrem, crop yang membuang konteks) dilarang. Yang sah adalah anotasi non-destruktif pada salinan, sementara file original disimpan utuh (idealnya dengan checksum/hash) untuk menjaga chain of custody.', 'Dokumentasi & Audit Trail', 'hard'),
  ('Untuk komponen kritis seperti pressure vessel ASME atau struktur jembatan, pendekatan retensi record inspeksi yang tepat adalah:',
   '["Boleh dimusnahkan setelah 30 hari karena konstruksi sudah selesai","Tidak perlu diarsipkan jika hasilnya accept","Retensi mengikuti code/kontrak/regulator — umumnya minimum 5 tahun, dan untuk komponen kritis bisa selama umur layanan (life-of-plant)","Disimpan inspektur secara pribadi tanpa backup"]', 2,
   'Periode retensi ditetapkan oleh code/kontrak/regulator; umumnya minimum 5 tahun dan untuk komponen kritis dapat selama umur layanan atau lebih. Memusnahkan record sebelum periode retensi habis adalah pelanggaran kewajiban hukum.', 'Dokumentasi & Audit Trail', 'medium'),
  ('Pada AWS D1.1 edisi terkini (2020/2025), di mana kriteria penerimaan inspeksi visual berada?',
   '["Section 6, Table 6.1","Annex K","Clause 4, Table 4.1","Clause 8, Table 8.1"]', 3,
   'Edisi terkini AWS D1.1 menempatkan Visual Inspection Acceptance Criteria di Clause 8, Table 8.1. Edisi 2015 dan sebelumnya memakai Section 6 / Table 6.1. Limit profil (convexity, reinforcement) dirujuk dari Clause 7.', 'Code Mastery AWS D1.1', 'easy'),
  ('Diskontinuitas berikut yang SELALU ditolak oleh AWS D1.1 tanpa memandang ukuran maupun kategori beban adalah:',
   '["Reinforcement setinggi 2 mm pada groove weld t = 12 mm","Crack (retak) ukuran apa pun","Convexity 2 mm pada fillet weld dengan W = 7 mm","Undercut 0.2 mm pada static compression t = 10 mm"]', 1,
   'Crack of any size/location adalah reject mutlak (Crack Prohibition), bersama incomplete fusion, incomplete penetration pada CJP, overlap, dan crater crack. Ketiga pilihan lain berada dalam limit yang diizinkan.', 'Code Mastery AWS D1.1', 'easy'),
  ('Sebuah fillet weld cyclically loaded yang transverse terhadap tegangan tarik (tension) ditemukan memiliki undercut 0.3 mm pada toe. Keputusan yang benar adalah:',
   '["Accept — di bawah 1 mm sehingga selalu lolos","Accept — undercut tidak pernah jadi masalah pada fillet","Reject — limit undercut transverse-to-tension cyclically loaded adalah 0.25 mm (0.01 in)","Reject — semua undercut pada fillet weld ditolak"]', 2,
   'Pada cyclically loaded yang transverse terhadap tensile stress, undercut tidak boleh melebihi 0.25 mm (0.01 in). 0.3 mm melebihi limit ini sehingga REJECT. Pada static loaded (t < 25 mm) limitnya 1 mm.', 'Code Mastery AWS D1.1', 'medium'),
  ('Untuk sambungan statically loaded dengan tebal material kurang dari 25 mm (1 in), berapa kedalaman undercut maksimum yang diizinkan AWS D1.1?',
   '["0.25 mm (0.01 in)","1 mm (1/32 in)","3 mm (1/8 in)","Tidak ada undercut yang diizinkan"]', 1,
   'Statically loaded untuk material < 25 mm mengizinkan undercut maksimum 1 mm (1/32 in); untuk material >= 25 mm batasnya 2 mm (1/16 in). Cyclically loaded transverse-to-tension hanya 0.25 mm (0.01 in). Tidak ada threshold ''6 mm'' di D1.1.', 'Code Mastery AWS D1.1', 'medium'),
  ('Pada fillet weld dengan lebar muka las (W) lebih besar dari 8 mm tetapi kurang dari 25 mm, berapa convexity maksimum yang diizinkan AWS D1.1 (Table 7.9)?',
   '["2 mm (1/16 in)","3 mm (1/8 in)","5 mm (3/16 in)","Tidak ada batas convexity"]', 1,
   'D1.1 membatasi convexity fillet berdasarkan lebar muka/bead (W): W <= 8 mm → maks 2 mm; W > 8 hingga < 25 mm → maks 3 mm; W >= 25 mm → maks 5 mm. Convexity berlebih menjadi stress raiser di toe.', 'Code Mastery AWS D1.1', 'hard'),
  ('Mengapa overlap (cold lap) di toe las selalu ditolak menurut AWS D1.1, berapa pun ukurannya?',
   '["Karena menambah tinggi reinforcement melebihi 3 mm","Karena selalu disertai porositas internal","Karena membuat throat menjadi terlalu tebal","Karena merupakan logam tanpa fusi yang menciptakan notch tajam (stress raiser)"]', 3,
   'Overlap adalah logam las yang meluap ke base metal tanpa fusi, menciptakan notch tajam di toe yang bertindak sebagai stress concentration dan titik inisiasi retak. Karena tidak ada fusi, ini reject zero-tolerance tanpa limit ukuran.', 'Code Mastery AWS D1.1', 'hard'),
  ('Sebuah fillet weld dengan ukuran nominal (S) yang diminta 8 mm ditemukan undersize. Menurut toleransi undersize D1.1, agar tetap acceptable berapa kekurangan (U) maksimum dan syaratnya?',
   '["U <= 3 mm (1/8 in), asalkan total panjang undersize <= 10% panjang las","U <= 0.25 mm, tanpa batas panjang","U <= 5 mm, asalkan tidak pada ujung las","Tidak ada undersize yang diizinkan; harus persis 8 mm"]', 0,
   'Untuk S >= 8 mm (5/16 in), undersize (U) yang diizinkan adalah <= 3 mm (1/8 in), dengan syarat total panjang bagian undersize tidak melebihi 10% panjang las. Untuk S lebih kecil (S = 3-5 mm → U <= 2 mm; S = 6 mm → U <= 2.5 mm), U yang diizinkan lebih kecil.', 'Code Mastery AWS D1.1', 'hard'),
  ('Untuk groove weld butt joint dengan tebal t <= 25 mm, reinforcement maksimum yang diizinkan AWS D1.1 (Table 7.9) adalah:',
   '["1 mm (1/32 in)","3 mm (1/8 in)","6 mm (1/4 in)","Tidak ada batas selama tidak ada crack"]', 1,
   'Reinforcement maksimum bergantung tebal: t <= 25 mm → maks 3 mm (1/8 in); t > 25 sampai 50 mm → maks 5 mm; t > 50 mm → maks 6 mm (tetapi maks 5 mm untuk cyclically loaded). Underfill tidak diizinkan; transisi toe harus gradual.', 'Code Mastery AWS D1.1', 'medium'),
  ('Dokumen AWS yang mengatur welding symbols (mis. menentukan apakah sambungan CJP atau PJP dan ukuran leg yang diminta) adalah:',
   '["AWS A2.4","AWS A3.0","AWS QC1","AWS D1.1"]', 0,
   'AWS A2.4 (Standard Symbols for Welding, Brazing, and NDE) adalah bahasa grafis di drawing. A3.0 adalah terminologi, QC1 adalah sertifikasi CWI, dan D1.1 adalah acceptance criteria struktural.', 'Code Mastery AWS D1.1', 'easy'),
  ('Pada CJP (Complete Joint Penetration) groove weld, incomplete penetration pada akar dinilai sebagai:',
   '["Diterima selama kurang dari 10% panjang las","Diterima jika reinforcement memadai untuk mengompensasi","Hanya dinilai dengan UT, bukan VT","Reject mutlak (zero-tolerance)"]', 3,
   'Incomplete penetration pada CJP groove weld adalah reject mutlak bersama crack, incomplete fusion, overlap, dan crater crack. Pada PJP, kedalaman penetrasi efektif harus memenuhi yang disyaratkan drawing/WPS.', 'Code Mastery AWS D1.1', 'medium'),
  ('Dalam terminologi AWS A3.0, perbedaan kunci antara ''discontinuity'' dan ''defect'' adalah:',
   '["Keduanya identik dan dapat dipertukarkan","Discontinuity belum tentu reject; defect adalah discontinuity yang melebihi kriteria penerimaan sehingga harus ditolak","Defect hanya ada di permukaan, discontinuity hanya subsurface","Discontinuity selalu lebih berbahaya daripada defect"]', 1,
   'A3.0 membedakan: discontinuity adalah ketidaksinambungan yang belum tentu rejectable, sedangkan defect adalah discontinuity yang melebihi kriteria penerimaan dan harus reject. Memakai istilah tepat krusial untuk validitas laporan.', 'Code Mastery AWS D1.1', 'medium'),
  ('AWS Certified Welding Inspector (CWI) dikelola di bawah dokumen spesifikasi:',
   '["AWS A2.4","AWS QC1","SNT-TC-1A","AWS B1.10"]', 1,
   'CWI dikelola American Welding Society di bawah AWS QC1 (Specification for AWS Certification of Welding Inspectors), yang mendefinisikan kategori, syarat, ujian, masa berlaku, renewal, dan recertification.', 'CWI Pathway', 'easy'),
  ('Ujian CWI terdiri atas tiga bagian. Bagian yang menggunakan replica weld specimen dan alat ukur (fillet/undercut gauge) untuk menilai terima/tolak terhadap Book of Specifications adalah:',
   '["Part A — Fundamentals (closed book)","Part B — Practical (open book)","Part C — Code Book (open book)","Part D — Vision Test"]', 1,
   'Part B (Practical) memakai Book of Specifications, replica weld specimen, dan alat ukur untuk mengukur profil las dan menilai terima/tolak. Inilah bagian yang paling bergantung pada skill pengukuran VT Level II. Tidak ada ''Part D'' pada ujian CWI.', 'CWI Pathway', 'medium'),
  ('Berapa skor minimum kelulusan untuk masing-masing dari tiga bagian ujian CWI menurut AWS QC1?',
   '["60%","80%","90%","72%"]', 3,
   'Ketiga bagian (A, B, C) harus dilulusi masing-masing dengan skor minimal 72%. Jika satu bagian gagal, hanya bagian itu yang perlu diulang dalam jendela retest yang ditentukan.', 'CWI Pathway', 'medium'),
  ('Persyaratan penglihatan dekat (near-vision) untuk CWI per AWS QC1 adalah:',
   '["Jaeger J2 (atau setara) pada jarak >=30 cm plus tes diferensiasi warna, diperiksa dalam 1 tahun sebelum ujian","Penglihatan jauh 6/6 tanpa tes warna","Hanya tes buta warna Ishihara sekali seumur hidup","Tidak ada syarat penglihatan untuk CWI"]', 0,
   'AWS QC1 menuntut near-vision Jaeger J2 (atau setara) pada jarak >=30 cm ditambah tes persepsi/diferensiasi warna, diperiksa tidak lebih dari 1 tahun sebelum ujian — selaras dengan disiplin persyaratan VT.', 'CWI Pathway', 'hard'),
  ('Pernyataan yang benar tentang hubungan CWI dan VT Level II adalah:',
   '["Memegang CWI otomatis memberi sertifikat VT Level II per SNT-TC-1A","Keduanya skema berbeda (AWS QC1 vs SNT-TC-1A/CP-189) yang saling memperkuat tetapi tidak saling menggantikan","VT Level II adalah level tertinggi sehingga CWI tidak diperlukan","CWI adalah sertifikasi metode NDT seperti VT/UT/RT"]', 1,
   'CWI dan VT Level II adalah skema berbeda di bawah dokumen berbeda; CWI tidak otomatis memberi VT Level II dan sebaliknya. CWI adalah sertifikasi peran inspektur las, bukan sertifikasi metode NDT. Keduanya saling memperkuat.', 'CWI Pathway', 'medium'),
  ('Dokumen AWS yang merupakan referensi langsung untuk teknik visual examination of welds adalah:',
   '["AWS B1.11 (Guide for Visual Examination of Welds)","AWS A2.4 (Welding Symbols)","AWS QC1 (Certification of WI)","AWS A3.0 (Terms and Definitions)"]', 0,
   'AWS B1.11 adalah panduan untuk visual examination of welds — referensi langsung teknik VT. A2.4 untuk simbol, A3.0 untuk terminologi, QC1 untuk sertifikasi inspektur. B1.10 adalah guide for NDE of welds secara umum.', 'CWI Pathway', 'hard'),
  ('Part A ujian CWI (Fundamentals) bersifat closed-book dan menguji terutama:',
   '["Navigasi AWS D1.1 untuk menemukan acceptance criteria","Pengukuran profil las pada replica specimen","Prinsip dasar welding process, simbol dasar, definisi cacat, dan metallurgy dasar","Hanya persyaratan penglihatan dan etika"]', 2,
   'Part A (closed book) menguji fundamental: welding process (SMAW/GMAW/FCAW/GTAW/SAW), simbol dasar, definisi diskontinuitas, metallurgy dasar, heat treatment, distorsi, dan safety. Navigasi code adalah Part C; pengukuran specimen adalah Part B.', 'CWI Pathway', 'medium'),
  ('Tiga kategori sertifikasi inspektur las di bawah AWS QC1, dari kewenangan terendah ke tertinggi, adalah:',
   '["CWI -> SCWI -> CAWI","Level I -> Level II -> Level III","Associate -> Senior -> Master","CAWI -> CWI -> SCWI"]', 3,
   'QC1 mendefinisikan: CAWI (Certified Associate WI, entry, di bawah supervisi), CWI (full inspector authority), dan SCWI (Senior CWI, dapat mengaudit dan mensupervisi program inspeksi).', 'CWI Pathway', 'medium'),
  ('Manakah pasangan diskontinuitas las berikut yang keduanya merupakan cacat PROFIL/permukaan yang dapat dinilai secara visual pada toe las?',
   '["Undercut dan overlap","Porositas internal dan slag inclusion subsurface","Lack of fusion subsurface dan laminasi","Hydrogen cracking subsurface dan inklusi tungsten"]', 0,
   'Undercut (alur tergerus di toe) dan overlap (cold lap di toe) keduanya cacat permukaan yang dapat dinilai dan diukur secara visual. Porositas internal, lack of fusion subsurface, dan crack subsurface memerlukan metode volumetrik.', 'Diskontinuitas Las', 'easy'),
  ('Seorang inspektur Level II mengukur undercut pada akar las internal pipa baja struktural (sambungan statis, t < 25 mm) memakai videoscope dan memperoleh estimasi 0,8 mm. Keputusan keberterimaan yang BENAR adalah:',
   '["Tolak otomatis karena setiap undercut tidak boleh ada pada las apa pun","Terima tanpa rujukan code karena nilai videoscope bersifat absolut","Bandingkan terhadap kriteria code; pada AWS D1.1 sambungan statis t < 25 mm undercut <=1 mm umumnya diterima, jadi 0,8 mm dapat diterima dengan dokumentasi","Tolak karena optical aid tidak boleh dipakai untuk pengukuran apa pun"]', 2,
   'Nilai borescope adalah estimasi yang dirujuk ke kriteria code. AWS D1.1 mengizinkan undercut hingga 1 mm untuk sambungan statis t < 25 mm, sehingga 0,8 mm dapat diterima dengan dokumentasi citra. Crack dan lack of fusion selalu ditolak, tetapi tidak setiap undercut otomatis ditolak.', 'Diskontinuitas Las', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- VT-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — VT-L2 scope', '{"description":"5 soal scope Level II + CWI pathway.","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- VT-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'VT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'VT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa perbedaan kewenangan paling mendasar antara VT Level I dan VT Level II menurut praktik SNT-TC-1A / ISO 9712?',
   '["Level I boleh menandatangani final acceptance, sedangkan Level II hanya membantu setup peralatan","Level I dan Level II memiliki kewenangan identik; perbedaannya hanya pada gaji","Level I melakukan pengujian sesuai instruksi/prosedur tertulis, sedangkan Level II menyusun teknik/prosedur, menafsirkan & mengevaluasi hasil terhadap code, serta menandatangani final acceptance","Level II tidak boleh menyentuh peralatan dan hanya menulis laporan administratif"]', 2,
   'Level I qualified untuk melakukan pengujian dan mencatat hasil mengikuti instruksi/prosedur tertulis di bawah pengawasan, tetapi tidak menentukan keberterimaan secara independen. Level II berwenang menyusun & mengkualifikasi teknik/prosedur, menafsirkan dan mengevaluasi indikasi terhadap acceptance code, menandatangani final acceptance, serta membimbing Level I. Kewenangan bukan sekadar soal gaji.', 'Scope & Authority', 'easy'),
  ('Manakah berikut ini yang merupakan tanggung jawab TAMBAHAN seorang VT Level II dibanding Level I?',
   '["Mengembangkan & mengkualifikasi teknik, mengoperasikan peralatan optik lanjutan (RVT), menandatangani sign-off acceptance, dan mementori Level I","Membersihkan permukaan benda uji sebelum inspeksi","Menyalakan lampu dan mengukur iluminasi dengan lux meter","Mencatat hasil pada formulir yang sudah diisi sebelumnya tanpa interpretasi"]', 0,
   'Tanggung jawab khas Level II mencakup pengembangan & kualifikasi teknik/prosedur, penguasaan peralatan lanjutan seperti remote visual testing (borescope/fiberscope/videoscope), kewenangan sign-off final acceptance, serta pembinaan (mentoring) dan supervisi Level I. Membersihkan permukaan, mengukur iluminasi, dan mencatat hasil sesuai instruksi adalah aktivitas yang juga dapat dilakukan Level I.', 'Level II Responsibilities', 'medium'),
  ('Dalam jalur karier seorang VT inspector, bagaimana hubungan antara sertifikasi VT Level II (SNT-TC-1A) dan sertifikasi AWS Certified Welding Inspector (CWI)?',
   '["Memegang VT Level II secara otomatis memberikan sertifikat CWI tanpa ujian terpisah","CWI berada satu tingkat di bawah VT Level II dan tidak relevan bagi inspektur las","Keduanya adalah skema berbeda di bawah badan/standar yang berbeda — VT Level II di bawah SNT-TC-1A, CWI di bawah AWS QC1 — namun keterampilan VT Level II menjadi fondasi praktis yang langsung dipakai di ujian CWI","VT Level II dan CWI mengukur kompetensi yang persis sama sehingga salah satunya redundan"]', 2,
   'VT Level II (di bawah recommended practice SNT-TC-1A, atau CP-189) dan CWI (di bawah standar AWS QC1) adalah dua skema sertifikasi terpisah dengan badan/dokumen acuan berbeda; memegang yang satu tidak otomatis memberikan yang lain dan masing-masing punya ujiannya sendiri. Namun keterampilan visual & pengukuran profil las dari VT Level II menjadi fondasi praktis yang langsung berguna pada ujian CWI (khususnya Part B Practical), sehingga keduanya saling memperkuat dalam jalur karier.', 'CWI Pathway', 'medium'),
  ('Menurut SNT-TC-1A, jalur kualifikasi Level II yang umum bagi seseorang yang sudah disertifikasi Level I pada metode yang sama adalah:',
   '["Otomatis naik ke Level II setelah satu tahun tanpa pelatihan atau ujian tambahan","Memenuhi jam pelatihan formal tambahan dan jam pengalaman tambahan untuk metode tersebut, lalu lulus ujian (general, specific, practical) sesuai Written Practice perusahaan","Cukup lulus ujian general saja tanpa ujian praktik","Hanya perlu rekomendasi lisan dari atasan tanpa dokumentasi"]', 1,
   'SNT-TC-1A adalah recommended practice; perusahaan menetapkan persyaratan rinci dalam Written Practice-nya. Kenaikan ke Level II menuntut jam pelatihan formal tambahan dan akumulasi jam pengalaman pada metode tersebut, ditambah kelulusan ujian general, specific, dan practical. Tidak ada kenaikan otomatis tanpa pelatihan/ujian, dan ujian praktik tidak boleh diabaikan.', 'Certification Requirements', 'hard'),
  ('Seorang VT Level I selesai memeriksa sambungan las dan mengisi laporan hasil pengamatan. Siapa yang BERWENANG menentukan keberterimaan akhir (final accept/reject) sambungan tersebut dan atas dasar apa?',
   '["Level II meninjau & menafsirkan hasil terhadap acceptance code yang berlaku, lalu menandatangani disposition final accept/reject","Level I langsung menandatangani disposition accept/reject karena ia yang melakukan pengamatan","Sambungan dianggap accept secara default jika Level I tidak menulis catatan reject","Welder yang mengelas berhak menentukan accept/reject atas pekerjaannya sendiri"]', 0,
   'Penentuan keberterimaan akhir adalah kewenangan Level II (atau lebih tinggi): ia menafsirkan dan mengevaluasi indikasi terhadap kriteria code yang berlaku lalu menandatangani disposition. Level I mencatat hasil pengamatan tetapi tidak melakukan evaluasi keberterimaan independen, tidak ada accept default, dan welder tidak boleh menilai pekerjaannya sendiri (konflik kepentingan).', 'Scope & Authority', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'VT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;
